(window.JCPA_DATA=window.JCPA_DATA||{})["insolvency_sys"]={"id":"insolvency_sys","name":"نظام الإعسار","full":"نظام الإعسار رقم (8) لسنة 2019","icon":"📑","articles":[{"n":"1","chapter":"","notes":[],"source":"يسمى هذا النظام (نظام الإعسار لسنة 2019) ويعمل به من تاريخ نشره في الجريدة الرسمية.","title":"اسم النظام وبدء العمل به","memo":"⭐ نظام الإعسار لسنة 2019 يعمل به من تاريخ نشره في الجريدة الرسمية","qs":[{"q":"متى يبدأ العمل بنظام الإعسار لسنة 2019؟","o":["من تاريخ نشره في الجريدة الرسمية","بعد ثلاثين يوما من تاريخ نشره في الجريدة الرسمية","من تاريخ إقراره من مجلس الوزراء","من بداية السنة المالية التالية لنشره"],"a":0}]},{"n":"2","chapter":"","notes":[],"source":"أ. يكون للكلمات التالية حيثما وردت في هذا النظام المعاني المخصصة لها أدناه ما لم تدل القرينة على غير ذلك:\nالقانون : قانون الإعسار.\nالوزارة : وزارة الصناعة والتجارة والتموين .\nالوزير : وزير الصناعة والتجارة والتموين .\nالدائرة : دائرة مراقبة الشركات في الوزارة.\nالمراقب : مراقب عام الشركات.\nالمسجل : موظف الدائرة الذي يسميه المراقب لمسك السجل والإشراف عليه.\nاللجنة : لجنة وكلاء الإعسار المشكلة بموجب أحكام هذا النظام.\nالوحدة : وحدة ترخيص وكلاء الإعسار والرقابة عليهم المنشأة في الدائرة وفقا لأحكام هذا النظام.\nب. تعتمد التعاريف الواردة في القانون حيثما ورد النص عليها في هذا النظام ما لم تدل القرينة على غير ذلك .","title":"التعاريف","memo":"⭐ الوزير: وزير الصناعة والتجارة والتموين\n⭐ الدائرة: دائرة مراقبة الشركات في الوزارة، والمراقب: مراقب عام الشركات\n⭐ المسجل: موظف الدائرة الذي يسميه المراقب لمسك السجل والإشراف عليه\n⭐ الوحدة: وحدة ترخيص وكلاء الإعسار والرقابة عليهم المنشأة في الدائرة","qs":[{"q":"وفقا لنظام الإعسار، يقصد بـ(الدائرة):","o":["دائرة مراقبة الشركات في الوزارة","دائرة التنفيذ في المحكمة","دائرة الأراضي والمساحة","دائرة ضريبة الدخل والمبيعات"],"a":0},{"q":"من الذي يسمي (المسجل) لمسك سجل الإعسار والإشراف عليه؟","o":["المراقب","الوزير","لجنة وكلاء الإعسار","المحكمة المختصة"],"a":0},{"q":"يقصد بـ(الوزير) في نظام الإعسار:","o":["وزير الصناعة والتجارة والتموين","وزير العدل","وزير المالية","وزير الاقتصاد الرقمي والريادة"],"a":0},{"q":"تنشأ (وحدة ترخيص وكلاء الإعسار والرقابة عليهم) في:","o":["دائرة مراقبة الشركات","وزارة العدل","هيئة الأوراق المالية","جمعية المحاسبين القانونيين الأردنيين"],"a":0}]},{"n":"3","chapter":"","notes":[],"source":"تسري أحكام هذا النظام على إجراءات الإعسار المقررة وفق أحكام القانون.","title":"نطاق سريان النظام","memo":"⭐ تسري أحكام النظام على إجراءات الإعسار المقررة وفق أحكام قانون الإعسار","qs":[{"q":"على ماذا تسري أحكام نظام الإعسار؟","o":["إجراءات الإعسار المقررة وفق أحكام قانون الإعسار","إجراءات تصفية الشركات الاختيارية فقط","إجراءات التنفيذ على أموال المدين بموجب قانون التنفيذ","إجراءات الإفلاس وفق قانون التجارة فقط"],"a":0}]},{"n":"4","chapter":"","notes":[],"source":"أ. ينشأ في الدائرة سجل إلكتروني موحد يسمى (سجل الإعسار) يتم فيه إشهار البيانات والمعلومات واجراءات الإعسار المبينة في القانون وفي هذا النظام.\nب. يكون السجل متاحا للعموم ويتم من خلاله تسجيل واشهار ما يلي :\n1. قرار إشهار الإعسار الصادر عن المحكمة.\n2. واقعة قيام وكيل الاعسار بإيداع تقرير المحاسبة النهائي وملاحظات لجنة الدائنين .\n3. واقعة إعداد قائمة الدائنين والمطالبات والوثائق المرفقة بها.\n4. إعلان المحكمة انتهاء المرحلة التمهيدية وبدء مرحلة إعادة التنظيم .\n5. وقائع اجتماع الهيئة العامة للدائنين .\n6. قرار المحكمة المتعلق بالاعتراضات المقدمة على خطة إعادة التنظيم .\n7. قرار بدء مرحلة التصفية الصادر عن المحكمة.\n8. إيداع خطة التصفية لدى المحكمة بعد اتمام التوزيع.\n9. انتهاء إجراءات الإعسار .\n10. أي قرار أو واقعة خاصة بإجراءات الإعسار ينص هذا النظام أو تقرر المحكمة اشهارها في السجل.\nج. للمراقب أن يقرر ربط السجل بأي سجلات في المملكة بما فيها سجل الشركات والسجل المركزي في الوزارة والسجل العدلي والسجل العقاري وسجل الحقوق على الأموال المنقولة وسجل المعلومات الائتمانية وذلك بعد التنسيق مع الجهات المختصة بإدارة هذه السجلات وتشغيلها .\nد. لمجلس الوزراء بناء على تنسيب الوزير أن يقرر ربط السجل بأي سجل إعسار في دولة أخرى من خلال اتفاقيات ثنائية تسمح بتبادل البيانات والمعلومات مع هذه السجلات .\nهـ. للمراقب أن يصدر التعليمات اللازمة لاعتماد سجل إعسار ورقي إلى حين استكمال إجراءات انشاء السجل الالكتروني.","title":"سجل الإعسار","memo":"⭐ ينشأ في الدائرة سجل إلكتروني موحد يسمى (سجل الإعسار) متاح للعموم\n⭐ للمراقب ربط السجل بأي سجلات في المملكة بعد التنسيق مع الجهات المختصة\n⭐ لمجلس الوزراء بتنسيب الوزير ربط السجل بسجل إعسار في دولة أخرى باتفاقيات ثنائية\n⭐ للمراقب إصدار تعليمات لاعتماد سجل ورقي إلى حين استكمال السجل الإلكتروني","qs":[{"q":"من صاحب الصلاحية في ربط سجل الإعسار بأي سجل إعسار في دولة أخرى؟","o":["مجلس الوزراء بناء على تنسيب الوزير","المراقب بعد التنسيق مع الجهات المختصة","الوزير بناء على تنسيب المراقب","لجنة وكلاء الإعسار"],"a":0},{"q":"للمراقب أن يقرر ربط سجل الإعسار بسجلات في المملكة، وذلك:","o":["بعد التنسيق مع الجهات المختصة بإدارة هذه السجلات وتشغيلها","بعد موافقة مجلس الوزراء","بعد موافقة المحكمة المختصة","بموجب اتفاقيات ثنائية"],"a":0},{"q":"أي مما يلي لا يعد من البيانات التي يتم تسجيلها وإشهارها في سجل الإعسار وفق النظام؟","o":["قرار لجنة وكلاء الإعسار بترخيص وكيل الإعسار","قرار إشهار الإعسار الصادر عن المحكمة","قرار بدء مرحلة التصفية الصادر عن المحكمة","وقائع اجتماع الهيئة العامة للدائنين"],"a":0},{"q":"إلى حين استكمال إجراءات إنشاء سجل الإعسار الإلكتروني:","o":["للمراقب إصدار التعليمات اللازمة لاعتماد سجل إعسار ورقي","توقف إجراءات الإشهار كافة","يتم الإشهار في الجريدة الرسمية فقط","يتولى سجل الشركات الإشهار نيابة عنه"],"a":0}]},{"n":"5","chapter":"الفصل الأول - سجل الإعسار","notes":[],"source":"أ. لا يتحمل المسجل أي مسؤولية عن عدم صحة البيانات والمعلومات التي يتم إشهارها في السجل أو دقتها وتبقى الجهة التي قامت بالإشهار مسؤولة عن صحة هذه البيانات والمعلومات ودقتها.\nب. لا يرتب الإشهار أي حق لأي جهة أو ينتقص منه أو يسقطه .","title":"مسؤولية المسجل وأثر الإشهار","memo":"⭐ لا يتحمل المسجل أي مسؤولية عن صحة البيانات المشهرة أو دقتها، والمسؤولية على الجهة التي قامت بالإشهار\n⭐ الإشهار لا يرتب أي حق ولا ينتقص منه ولا يسقطه","qs":[{"q":"من يتحمل المسؤولية عن صحة البيانات والمعلومات المشهرة في سجل الإعسار ودقتها؟","o":["الجهة التي قامت بالإشهار","المسجل","المراقب","الدائرة"],"a":0},{"q":"ما الأثر القانوني لإشهار البيانات في سجل الإعسار على الحقوق؟","o":["لا يرتب أي حق لأي جهة ولا ينتقص منه ولا يسقطه","ينشئ حقا للجهة التي قامت بالإشهار","يسقط حقوق من لم يعترض على الإشهار","يرتب أولوية للدائن الأسبق في الإشهار"],"a":0}]},{"n":"6","chapter":"الفصل الأول - سجل الإعسار","notes":[],"source":"أ. لا يجوز اشهار أي بيانات أو معلومات شخصية تتعلق بالمدين أو بأي من أطراف اجراءات الإعسار من الأشخاص الطبيعيين في السجل باستثناء البيانات والمعلومات التي يوجب القانون اشهارها وفي الحدود المبينة فيه.\nب. لا يجوز استخدام البيانات أو المعلومات المشهرة في السجل لغير الأغراض المنصوص عليها في القانون وعلى المسجل اتخاذ الإجراءات اللازمة للمحافظة على سرية المعلومات الشخصية المشهرة في السجل.\nج. يجوز لأي شخص الاعتراض على بيانات الإشهار من خلال الموقع الالكتروني وفق الإجراءات المنصوص عليها في التعليمات التي يصدرها المراقب لهذه الغاية.","title":"حماية البيانات الشخصية في السجل","memo":"⭐ لا يجوز إشهار بيانات شخصية للأشخاص الطبيعيين إلا ما يوجب القانون إشهاره وفي حدوده\n⭐ لا يجوز استخدام البيانات المشهرة لغير أغراض القانون\n⭐ لأي شخص الاعتراض على بيانات الإشهار عبر الموقع الإلكتروني وفق تعليمات المراقب","qs":[{"q":"الأصل في إشهار البيانات الشخصية المتعلقة بالمدين من الأشخاص الطبيعيين في سجل الإعسار أنه:","o":["لا يجوز إلا للبيانات التي يوجب القانون إشهارها وفي الحدود المبينة فيه","يجوز دون قيد لأن السجل متاح للعموم","يجوز بموافقة المسجل","يجوز بموافقة الدائنين"],"a":0},{"q":"كيف يتم الاعتراض على بيانات الإشهار في سجل الإعسار؟","o":["من خلال الموقع الإلكتروني وفق التعليمات التي يصدرها المراقب","بدعوى أمام المحكمة المختصة فقط","بطلب خطي إلى الوزير","بتظلم إلى لجنة وكلاء الإعسار"],"a":0},{"q":"من الملزم باتخاذ الإجراءات اللازمة للمحافظة على سرية المعلومات الشخصية المشهرة في السجل؟","o":["المسجل","وكيل الإعسار","لجنة الدائنين","الوزير"],"a":0}]},{"n":"7","chapter":"الفصل الأول - سجل الإعسار","notes":[],"source":"تنظم الإشهارات من خلال الموقع الإلكتروني للسجل باللغة العربية وفق النماذج الإلكترونية المعدة لهذه الغاية على أنه يجوز استعمال أحرف ورموز من أي لغة أخرى إذا تعذر إتمام الإشهارات إلا باستخدام تلك اللغة .","title":"لغة الإشهارات","memo":"⭐ تنظم الإشهارات عبر الموقع الإلكتروني باللغة العربية وفق النماذج الإلكترونية\n⭐ يجوز استعمال أحرف ورموز لغة أخرى إذا تعذر إتمام الإشهار إلا بها","qs":[{"q":"ما اللغة التي تنظم بها الإشهارات في سجل الإعسار؟","o":["اللغة العربية، ويجوز استعمال أحرف ورموز لغة أخرى إذا تعذر الإشهار إلا بها","اللغة العربية أو الإنجليزية حسب اختيار المشهر","اللغة الإنجليزية لكل ما يتعلق بالمدينين الأجانب","أي لغة تحددها المحكمة"],"a":0},{"q":"تنظم الإشهارات في سجل الإعسار:","o":["من خلال الموقع الإلكتروني للسجل وفق النماذج الإلكترونية المعدة لهذه الغاية","بالنشر في صحيفتين يوميتين","بإيداع ورقي لدى قلم المحكمة","بقرار من الوزير"],"a":0}]},{"n":"8","chapter":"الفصل الأول - سجل الإعسار","notes":[],"source":"أ. يشترط في أي شخص يتولى أعمال وكيل الإعسار أن يكون مرخصا وفق أحكام القانون وهذا النظام.\nب. الى حين ترخيص وكلاء إعسار، يجوز للمحكمة أن تعين وكلاء إعسار من الأشخاص الطبيعيين شريطة أن تتوافر فيهم الشروط المنصوص عليها في البنود (1) و (2) و (3) و ( 4) و (5) من الفقرة (أ) من المادة (14) من هذا النظام وللمحكمة أن تكلف وكيل الإعسار المعين بتقديم الوثائق والمستندات التي تراها مناسبة لاثبات استيفائه لتلك الشروط .","title":"اشتراط ترخيص وكيل الإعسار","memo":"⭐ يشترط فيمن يتولى أعمال وكيل الإعسار أن يكون مرخصا\n⭐ إلى حين ترخيص وكلاء إعسار يجوز للمحكمة تعيين وكلاء من الأشخاص الطبيعيين تتوافر فيهم البنود (1)-(5) من الفقرة (أ) من المادة (14)","qs":[{"q":"إلى حين ترخيص وكلاء إعسار، يجوز للمحكمة أن تعين وكلاء إعسار:","o":["من الأشخاص الطبيعيين الذين تتوافر فيهم شروط محددة من المادة (14) من النظام","من الأشخاص الاعتباريين فقط","من موظفي دائرة مراقبة الشركات فقط","من أي شخص دون شروط"],"a":0},{"q":"خلال المرحلة الانتقالية قبل ترخيص وكلاء الإعسار، أي من الشروط التالية لا يشترط في وكيل الإعسار الذي تعينه المحكمة؟","o":["اجتياز الامتحان المقرر للترخيص","أن يكون أردني الجنسية","أن يكون قد بلغ ثلاثين عاما","ألا يكون محكوما عليه بجناية أو بجنحة مخلة بالشرف"],"a":0}]},{"n":"9","chapter":"الفصل الثاني - ترخيص وكلاء الإعسار","notes":[],"source":"أ. تشكل لجنة تسمى (لجنة وكلاء الإعسار) برئاسة الوزير وعضوية كل من:\n1. وزير العدل نائبا للرئيس.\n2. رئيس مجلس مفوضي هيئة الأوراق المالية.\n3. المراقب.\n4. رئيس غرفة تجارة الأردن\n5. رئيس جمعية المحاسبين القانونيين الأردنيين عميد كلية الحقوق في أي من الجامعات الرسمية التي يختارها رئيس اللجنة لمدة سنتين غير قابلة للتجديد.\nب. يتقاضى أعضاء اللجنة المنصوص عليهم في الفقرة (أ) من هذه المادة بدلات العضوية التي يحددها مجلس الوزراء.","title":"تشكيل لجنة وكلاء الإعسار","memo":"⭐ لجنة وكلاء الإعسار برئاسة الوزير، ووزير العدل نائبا للرئيس\n⭐ من أعضائها: رئيس مجلس مفوضي هيئة الأوراق المالية، المراقب، رئيس غرفة تجارة الأردن، رئيس جمعية المحاسبين القانونيين، وعميد كلية حقوق في جامعة رسمية يختاره رئيس اللجنة لمدة سنتين غير قابلة للتجديد\n⭐ بدلات العضوية يحددها مجلس الوزراء","qs":[{"q":"من يرأس لجنة وكلاء الإعسار؟","o":["وزير الصناعة والتجارة والتموين","وزير العدل","مراقب عام الشركات","رئيس مجلس مفوضي هيئة الأوراق المالية"],"a":0},{"q":"من يكون نائبا لرئيس لجنة وكلاء الإعسار؟","o":["وزير العدل","المراقب","رئيس غرفة تجارة الأردن","رئيس جمعية المحاسبين القانونيين الأردنيين"],"a":0},{"q":"يحدد بدلات عضوية أعضاء لجنة وكلاء الإعسار:","o":["مجلس الوزراء","الوزير","رئيس اللجنة","المراقب"],"a":0},{"q":"مدة عضوية عميد كلية الحقوق في لجنة وكلاء الإعسار هي:","o":["سنتان غير قابلة للتجديد","سنتان قابلة للتجديد مرة واحدة","ثلاث سنوات غير قابلة للتجديد","أربع سنوات قابلة للتجديد"],"a":0}]},{"n":"10","chapter":"الفصل الثاني - ترخيص وكلاء الإعسار","notes":[],"source":"تتولى اللجنة المهام والصلاحيات التالية:\nأ. تنظيم امتحان ترخيص وكلاء الإعسار بما في ذلك تعيين لجنة الامتحان لتتولى وضع لائحة بموضوعات الامتحان واعتماد اسئلته وإقرار الترتيبات المتعلقة به من حيث المكان والزمان وكل ما يتطلبه من إجراءات والإشراف على تصحيحه وإعداد قائمة بأسماء الأشخاص الذين تقدموا له ودرجاتهم والناجحين منهم والقيام بأي أعمال تتعلق به.\nب. المصادقة على نتائج الامتحان المرفوعة من لجنة الامتحان.\nج. إعداد واعتماد قواعد سلوك مهنة وكيل الإعسار وآدابها ومعايير جودتها.\nد. ترخيص وكلاء الإعسار وتجديد تراخيصهم ووقفها وإلغاؤها وفقا لأحكام هذا النظام.\nهـ. الرقابة على وكلاء الإعسار المرخصين بما في ذلك الطلب منهم تزويدها بالمعلومات والبيانات اللازمة لممارسة رقابتها عليهم واتخاذ الإجراءات التأديبية بحق المخالفين وفقا لأحكام القانون وهذا النظام والتعليمات الصادرة بمقتضاه.\nو. النظر في الشكاوى المقدمة ضد وكلاء الإعسار والبت فيها واتخاذ الإجراءات اللازمة بخصوصها.\nز. وضع خطة للتعليم المستمر والدورات التدريبية لوكلاء الإعسار بالتعاون مع الجهة التي تختارها اللجنة لبناء قدراتهم من خلال تنظيم ورشات عمل ومحاضرات ومؤتمرات خاصة بالمهنة.","title":"مهام لجنة وكلاء الإعسار","memo":"⭐ تنظم امتحان الترخيص وتعين لجنة الامتحان وتصادق على نتائجه\n⭐ تعد وتعتمد قواعد سلوك المهنة وآدابها ومعايير جودتها\n⭐ ترخص الوكلاء وتجدد تراخيصهم وتوقفها وتلغيها وتراقبهم وتنظر الشكاوى ضدهم\n⭐ تضع خطة التعليم المستمر والدورات التدريبية","qs":[{"q":"من يصادق على نتائج امتحان ترخيص وكلاء الإعسار؟","o":["لجنة وكلاء الإعسار","لجنة الامتحان","وحدة ترخيص وكلاء الإعسار","الوزير"],"a":0},{"q":"الجهة المختصة بإعداد واعتماد قواعد سلوك مهنة وكيل الإعسار وآدابها ومعايير جودتها هي:","o":["لجنة وكلاء الإعسار","جمعية المحاسبين القانونيين الأردنيين","المحكمة المختصة","مجلس الوزراء"],"a":0},{"q":"أي مما يلي لا يعد من مهام لجنة وكلاء الإعسار؟","o":["تحديد أتعاب وكيل الإعسار في دعوى الإعسار","النظر في الشكاوى المقدمة ضد وكلاء الإعسار والبت فيها","ترخيص وكلاء الإعسار وتجديد تراخيصهم ووقفها وإلغاؤها","وضع خطة للتعليم المستمر لوكلاء الإعسار"],"a":0}]},{"n":"11","chapter":"الفصل الثاني - ترخيص وكلاء الإعسار","notes":[],"source":"أ. تجتمع اللجنة بدعوة من رئيسها أو نائبه في حال غيابه.\nب. يكون النصاب القانوني لاجتماع اللجنة بحضور ما لا يقل عن خمسة من أعضائها على ان يكون الرئيس او نائبه من بينهم وتتخذ قراراتها بأغلبية أصوات الأعضاء الحاضرين وعند تساوي الأصوات يرجح الجانب الذي صوت معه رئيس الاجتماع.\nج. للجنة دعوة من تراه مناسبا من ذوي الخبرة والاختصاص لحضور اجتماعها دون ان يكون له حق التصويت على قراراتها.","title":"اجتماعات لجنة وكلاء الإعسار","memo":"⭐ تجتمع بدعوة من رئيسها أو نائبه عند غيابه\n⭐ النصاب: حضور خمسة أعضاء على الأقل بينهم الرئيس أو نائبه\n⭐ القرارات بأغلبية الحاضرين، وعند التساوي يرجح جانب رئيس الاجتماع\n⭐ لها دعوة ذوي الخبرة دون حق التصويت","qs":[{"q":"ما النصاب القانوني لاجتماع لجنة وكلاء الإعسار؟","o":["حضور خمسة من أعضائها على الأقل على أن يكون الرئيس أو نائبه من بينهم","حضور أربعة من أعضائها على الأقل","حضور الأغلبية المطلقة للأعضاء دون اشتراط حضور الرئيس","حضور جميع الأعضاء"],"a":0},{"q":"في حال تساوي الأصوات في لجنة وكلاء الإعسار:","o":["يرجح الجانب الذي صوت معه رئيس الاجتماع","يعاد التصويت في جلسة لاحقة","يعتبر القرار مرفوضا","يرفع الأمر إلى مجلس الوزراء"],"a":0},{"q":"دعت لجنة وكلاء الإعسار خبيرا لحضور اجتماعها، فما حكم مشاركته في التصويت؟","o":["يحضر دون أن يكون له حق التصويت","له حق التصويت كسائر الأعضاء","له حق التصويت عند تساوي الأصوات فقط","يصوت بموافقة رئيس اللجنة"],"a":0}]},{"n":"12","chapter":"الفصل الثاني - ترخيص وكلاء الإعسار","notes":[],"source":"يكلف الوزير من بين موظفي الوحدة أمينا لسر اللجنة يتولى المهام والمسؤوليات التالية:\nأ. توزيع الدعوة لاجتماعات اللجنة .\nب. تدوين محاضر جلسات اللجنة وحفظ قراراتها.\nج. حفظ وتبويب القرارات الصادرة عن اللجنة والملفات والمستندات والتقارير المتعلقة بعملها.\nد. حفظ ملفات الشكاوى المقدمة ضد وكلاء الإعسار المرخصين والملفات والمستندات والتقارير المتعلقة بها.\nهـ. أي مهام أخرى تعهد له اللجنة بها.","title":"أمين سر لجنة وكلاء الإعسار","memo":"⭐ يكلف الوزير أمين سر اللجنة من بين موظفي الوحدة\n⭐ يتولى توزيع الدعوات وتدوين المحاضر وحفظ القرارات وملفات الشكاوى","qs":[{"q":"من يكلف أمين سر لجنة وكلاء الإعسار؟","o":["الوزير من بين موظفي الوحدة","رئيس اللجنة من بين أعضائها","المراقب من بين موظفي الدائرة","اللجنة من بين وكلاء الإعسار المرخصين"],"a":0},{"q":"أي مما يلي لا يعد من مهام أمين سر لجنة وكلاء الإعسار؟","o":["البت في الشكاوى المقدمة ضد وكلاء الإعسار","توزيع الدعوة لاجتماعات اللجنة","تدوين محاضر جلسات اللجنة وحفظ قراراتها","حفظ ملفات الشكاوى المقدمة ضد وكلاء الإعسار"],"a":0}]},{"n":"13","chapter":"الفصل الثاني - ترخيص وكلاء الإعسار","notes":[],"source":"تنشأ في الدائرة وحدة تسمى (وحدة ترخيص وكلاء الاعسار والرقابة عليهم) تتولى المهام التالية:\nأ. استلام طلبات ترخيص وكلاء الإعسار وطلبات تجديد تراخيصهم ووقفها ورفعها للجنة للبت بها.\nب. التنسيق مع لجنة الامتحان لإجراء الترتيبات اللازمة لعقد امتحان وكلاء الإعسار وفقا للآلية التي تحددها اللجنة.\nج. التدقيق على وكلاء الإعسار للوقوف على التزامهم بأحكام القانون وهذا النظام والتعليمات الصادرة بموجبه.\nد. التحقق من الشكاوى المقدمة بشأن أي من وكلاء الإعسار والمحالة لها من اللجنة ورفع توصياتها للجنة لاتخاذ القرار المناسب بشأنها.\nهـ. التحقق من التزام وكلاء الإعسار بشروط ومتطلبات الترخيص.\nو. أي أمور أخرى تكلفها اللجنة بها.","title":"وحدة ترخيص وكلاء الإعسار والرقابة عليهم","memo":"⭐ تنشأ في الدائرة وتستلم طلبات الترخيص والتجديد والوقف وترفعها للجنة للبت\n⭐ تنسق مع لجنة الامتحان، وتدقق على الوكلاء وتتحقق من التزامهم\n⭐ تتحقق من الشكاوى المحالة من اللجنة وترفع توصياتها للجنة","qs":[{"q":"الجهة التي تستلم طلبات ترخيص وكلاء الإعسار وترفعها للجنة للبت فيها هي:","o":["وحدة ترخيص وكلاء الإعسار والرقابة عليهم","المسجل","المحكمة المختصة","أمين سر اللجنة"],"a":0},{"q":"ما دور الوحدة في الشكاوى المقدمة بشأن وكلاء الإعسار والمحالة لها من اللجنة؟","o":["التحقق منها ورفع توصياتها للجنة لاتخاذ القرار المناسب","البت فيها بقرار نهائي","إحالتها مباشرة إلى المحكمة","إحالتها إلى الجهة التحقيقية المختصة"],"a":0},{"q":"تنسق الوحدة مع لجنة الامتحان لعقد امتحان وكلاء الإعسار وفقا للآلية التي يحددها:","o":["لجنة وكلاء الإعسار","الوزير","المراقب","مجلس الوزراء"],"a":0}]},{"n":"14","chapter":"الفصل الثاني - ترخيص وكلاء الإعسار","notes":[],"source":"يشترط لترخيص وكيل الإعسار وتجديد ترخيصه اضافة إلى الشروط المنصوص عليها في القانون ما يلي:\nأ. إذا كان شخصا طبيعيا:\n1. أن يكون أردني الجنسية.\n2. أن يكون قد بلغ ثلاثين عاما بتاريخ تقديم الطلب.\n3. أن يكون حاصلا على شهادة جامعية في الاقتصاد أو إدارة الأعمال أو القانون أو المحاسبة أو الهندسة ولديه خبرة عملية لا تقل عن خمس سنوات في مجال عمله.\n4. ان لا يكون من ذوي الصلة بالمدين او تربطه به علاقة عمل او أي علاقة اخرى تؤثر على حياده.\n5. أن لا يكون محكوما عليه بجناية أو بجنحة مخلة بالشرف أو بالآداب والأخلاق العامة.\n6. أن يكمل دورة التدريب وفقا للشروط والمتطلبات التي تحددها اللجنة.\n7. أن يجتاز الامتحان المقرر للترخيص.\n8. أن يقدم ضمانات المسؤولية المدنية المنصوص عليها في المادة (56) من القانون وهذا النظام.\nب. إذا كان شخصا اعتباريا:\n1. أن يكون مسجلا كشركة مدنية مملوكة من قبل شخصين أو أكثر تتوافر فيهم الشروط المنصوص عليها في الفقرة (أ) من هذه المادة على ان تقدم الشركة الضمانات المنصوص عليها في البند (8) منها.\n2. أن يعمل في الشركة وكيلا إعسار على الأقل من الأشخاص الطبيعيين المرخصين.\nج. يلغى ترخيص وكيل الإعسار في حال فقدان أي من شروطه بقرار من اللجنة على أن يتم إشعار الجهة المختصة بذلك الإلغاء لتعميمه على المحاكم.","title":"شروط ترخيص وكيل الإعسار","memo":"⭐ الشخص الطبيعي: أردني، بلغ (30) عاما، شهادة جامعية في الاقتصاد أو إدارة الأعمال أو القانون أو المحاسبة أو الهندسة مع خبرة لا تقل عن (5) سنوات\n⭐ يكمل دورة التدريب ويجتاز الامتحان ويقدم ضمانات المسؤولية المدنية (م56 من القانون)\n⭐ الشخص الاعتباري: شركة مدنية يملكها شخصان أو أكثر مستوفيان للشروط ويعمل فيها وكيلا إعسار مرخصان على الأقل\n⭐ يلغى الترخيص بقرار من اللجنة عند فقدان أي شرط","qs":[{"q":"ما الحد الأدنى للعمر المشترط لترخيص وكيل الإعسار (الشخص الطبيعي)؟","o":["ثلاثون عاما بتاريخ تقديم الطلب","خمسة وعشرون عاما","ثمانية عشر عاما","خمسة وثلاثون عاما"],"a":0},{"q":"ما الحد الأدنى للخبرة العملية المطلوبة لترخيص وكيل الإعسار؟","o":["خمس سنوات في مجال عمله","ثلاث سنوات","سبع سنوات","عشر سنوات"],"a":0},{"q":"يشترط في الشخص الاعتباري لترخيصه وكيل إعسار أن يكون مسجلا كـ:","o":["شركة مدنية مملوكة من شخصين أو أكثر تتوافر فيهم شروط الشخص الطبيعي","شركة مساهمة عامة","شركة ذات مسؤولية محدودة برأسمال محدد","شركة تضامن مملوكة لمحامين فقط"],"a":0},{"q":"ما الحد الأدنى لعدد وكلاء الإعسار من الأشخاص الطبيعيين المرخصين الذين يعملون في الشخص الاعتباري المرخص؟","o":["اثنان","واحد","ثلاثة","خمسة"],"a":0}]},{"n":"15","chapter":"الفصل الثاني - ترخيص وكلاء الإعسار","notes":[],"source":"أ. يقدم طلب الترخيص إلى الوحدة وفق النموذج المعتمد من اللجنة موقعا من مقدمه أو المفوض بالتوقيع عنه إذا كان شخصا اعتباريا.\nب. يرفق طالب الترخيص بالطلب الوثائق التي تثبت استيفاءه شروط الترخيص المنصوص عليها في القانون وهذا النظام.","title":"تقديم طلب الترخيص","memo":"⭐ يقدم الطلب إلى الوحدة وفق النموذج المعتمد من اللجنة موقعا من مقدمه أو المفوض بالتوقيع عن الشخص الاعتباري\n⭐ ترفق به الوثائق التي تثبت استيفاء الشروط","qs":[{"q":"إلى أي جهة يقدم طلب ترخيص وكيل الإعسار؟","o":["الوحدة","المسجل","المحكمة المختصة","وزارة العدل"],"a":0},{"q":"يقدم طلب ترخيص وكيل الإعسار وفق النموذج المعتمد من:","o":["لجنة وكلاء الإعسار","الوزير","المراقب","مجلس الوزراء"],"a":0}]},{"n":"16","chapter":"الفصل الثاني - ترخيص وكلاء الإعسار","notes":[],"source":"أ. تفصل اللجنة في طلب الترخيص وفي حال استيفاء طالب الترخيص الشروط والمتطلبات المنصوص عليها في القانون وهذا النظام، تصدر اللجنة قرارها بالترخيص ولا يكون نافذا ما لم يتم استكمال الإجراءات والمتطلبات التالية:\n1. تسديد رسوم الترخيص المنصوص عليها في هذا النظام.\n2. تزويد الوحدة بضمانات المسؤولية المدنية المنصوص عليها في المادة (56) من القانون سواء على شكل كفالة بنكية أو بوليصة تأمين وبالشروط والصيغة والمبلغ المحددة في قرار الترخيص.\n3. استكمال أي شروط خاصة تضمنها قرار الترخيص.\n4. تأدية الشخص الطبيعي القسم أمام اللجنة بالصيغة التالية؛\n\" اقسم بالله العظيم ان اقوم بواجبات مهنتي بشرف وامانة دون تحيز وان اتقيد بالقوانين والانظمة والتعليمات المعمول بها وان احافظ على اسرار المهنة وآدابها وقواعدها \"\nب. حال استكمال المتطلبات المشار اليها أعلاه يتم قيد وكيل الإعسار في سجل وكلاء الإعسار المعد لهذه الغاية لدى الوحدة.","title":"نفاذ قرار الترخيص والقيد","memo":"⭐ يكون قرار الترخيص غير نافذ إلا بعد: تسديد الرسوم، وتقديم ضمانات المسؤولية المدنية (كفالة بنكية أو بوليصة تأمين)، واستكمال الشروط الخاصة، وأداء القسم أمام اللجنة\n⭐ بعد استكمال المتطلبات يقيد الوكيل في سجل وكلاء الإعسار لدى الوحدة","qs":[{"q":"أمام من يؤدي وكيل الإعسار (الشخص الطبيعي) القسم القانوني؟","o":["لجنة وكلاء الإعسار","الوزير","رئيس المحكمة المختصة","المراقب"],"a":0},{"q":"بأي شكل تقدم ضمانات المسؤولية المدنية لوكيل الإعسار؟","o":["كفالة بنكية أو بوليصة تأمين","رهن عقاري فقط","إيداع نقدي في حساب الدائرة فقط","كفالة شخصية من وكيل إعسار آخر"],"a":0},{"q":"صدر قرار اللجنة بترخيص وكيل إعسار لكنه لم يسدد رسوم الترخيص بعد، فما وضع قرار الترخيص؟","o":["لا يكون نافذا ما لم يتم استكمال المتطلبات ومنها تسديد الرسوم","يكون نافذا ويستوفى الرسم لاحقا","يعتبر ملغى حكما","يكون نافذا لمدة سنة واحدة"],"a":0}]},{"n":"17","chapter":"الفصل الثاني - ترخيص وكلاء الإعسار","notes":[],"source":"في حال رفض طلب الترخيص يبلغ مقدم الطلب بذلك.","title":"رفض طلب الترخيص","memo":"⭐ في حال رفض طلب الترخيص يبلغ مقدم الطلب بذلك","qs":[{"q":"ما الإجراء المقرر في حال رفض طلب ترخيص وكيل الإعسار؟","o":["يبلغ مقدم الطلب بذلك","يحال الطلب إلى المحكمة","يعاد الطلب إلى الوزير للبت فيه","ينشر الرفض في سجل الإعسار"],"a":0}]},{"n":"18","chapter":"الفصل الثاني - ترخيص وكلاء الإعسار","notes":[],"source":"تصدر اللجنة التعليمات اللازمة لتصنيف وكلاء الإعسار حال استكمال ترخيص (50) خمسين وكيل اعسار وقيدهم في السجل.","title":"تصنيف وكلاء الإعسار","memo":"⭐ تصدر اللجنة تعليمات تصنيف وكلاء الإعسار حال استكمال ترخيص (50) خمسين وكيلا وقيدهم في السجل","qs":[{"q":"متى تصدر لجنة وكلاء الإعسار التعليمات اللازمة لتصنيف وكلاء الإعسار؟","o":["حال استكمال ترخيص (50) وكيل إعسار وقيدهم في السجل","حال استكمال ترخيص (100) وكيل إعسار","بعد سنتين من نفاذ النظام","حال استكمال ترخيص (25) وكيل إعسار"],"a":0}]},{"n":"19","chapter":"الفصل الثاني - ترخيص وكلاء الإعسار","notes":[],"source":"أ. يلتزم وكيل الإعسار بتبليغ اللجنة بأي تغيير يطرأ على أي من البيانات والمعلومات التي تم ترخيصه بمقتضاها فور حدوثها.\nب. على وكيل الاعسار إعلام اللجنة في حال فقدانه أيا من شروط ترخيصه او ترخيص أي من وكلاء الاعسار الذين تم ترخيصه بناء على مؤهلاتهم.\nج. اذا كان وكيل الاعسار شخصا اعتباريا فعليه اعلام اللجنة عند انتهاء علاقته بأي من وكلاء الاعسار الذين تم ترخيصه بناء على مؤهلاتهم وفي حال نقص عدد وكلاء الإعسار العاملين لديه عن الحد الأدنى المنصوص عليه في البند (2) من الفقرة (ب) من المادة (14) من هذا النظام، فعليه تصويب الامر خلال ثلاثين يوما من تاريخ حدوث الواقعة.","title":"التزامات الإبلاغ على وكيل الإعسار","memo":"⭐ يبلغ الوكيل اللجنة بأي تغيير في بيانات ترخيصه فور حدوثه\n⭐ يعلم اللجنة عند فقدان أي من شروط ترخيصه\n⭐ الشخص الاعتباري الذي نقص عدد وكلائه عن الحد الأدنى يصوب الأمر خلال (30) يوما","qs":[{"q":"إذا نقص عدد وكلاء الإعسار العاملين لدى وكيل إعسار اعتباري عن الحد الأدنى، فعليه تصويب الأمر خلال:","o":["ثلاثين يوما من تاريخ حدوث الواقعة","ستين يوما","عشرة أيام","تسعين يوما"],"a":0},{"q":"متى يلتزم وكيل الإعسار بتبليغ اللجنة بأي تغيير يطرأ على بيانات ترخيصه؟","o":["فور حدوثه","خلال ثلاثين يوما","عند تقديم طلب التجديد","خلال ستين يوما"],"a":0}]},{"n":"20","chapter":"الفصل الثاني - ترخيص وكلاء الإعسار","notes":[],"source":"أ. تكون مدة الترخيص سنتين من تاريخ قيد وكيل الإعسار في سجل وكلاء الإعسار وفقا لأحكام الفقرة (ب) من المادة (16) من هذا النظام.\nب. على وكيل الإعسار تقديم طلب لتجديد ترخيصه قبل ستين يوما من تاريخ انتهائه وفقا للنموذج المعد لهذه الغاية معززا بما يلي:\n1. ما يثبت التحاقه بدورات التعليم المستمر التي تقرر اللجنة الزاميتها لغايات تجديد ترخيصه وإتمامه متطلبات التعليم المستمر المحددة من قبل اللجنة.\n2. أن يسدد رسوم التجديد المحددة في هذا النظام.","title":"مدة الترخيص وتجديده","memo":"⭐ مدة الترخيص سنتان من تاريخ قيد الوكيل في سجل وكلاء الإعسار\n⭐ يقدم طلب التجديد قبل (60) يوما من انتهائه\n⭐ يرفق ما يثبت إتمام متطلبات التعليم المستمر وتسديد رسوم التجديد","qs":[{"q":"ما مدة ترخيص وكيل الإعسار؟","o":["سنتان من تاريخ قيده في سجل وكلاء الإعسار","سنة واحدة من تاريخ صدور قرار الترخيص","ثلاث سنوات من تاريخ أداء القسم","خمس سنوات من تاريخ صدور قرار الترخيص"],"a":0},{"q":"على وكيل الإعسار تقديم طلب تجديد ترخيصه قبل انتهائه بـ:","o":["ستين يوما","ثلاثين يوما","تسعين يوما","عشرة أيام"],"a":0},{"q":"يحتسب بدء مدة ترخيص وكيل الإعسار من تاريخ:","o":["قيده في سجل وكلاء الإعسار","صدور قرار اللجنة بالترخيص","اجتيازه الامتحان","تقديم طلب الترخيص"],"a":0}]},{"n":"21","chapter":"الفصل الثاني - ترخيص وكلاء الإعسار","notes":[],"source":"على وكيل الإعسار أن يبذل في تنفيذ التزاماته وواجباته المنصوص عليها في القانون وهذا النظام عناية الرجل المعتاد في ماله الخاص بما في ذلك ما يلي:\nأ. تأدية عمله بكل أمانة وإخلاص والتزامه بقواعد سلوك المهنة وآدابها المعتمدة من قبل اللجنة.\nب. الإشراف الكامل والمباشر على أعماله وان لا يوكل لغيره مهام تتعلق بأعماله أو بجزء منها ما لم تأذن أو تصرح له المحكمة بذلك .\nج. التنحي عن أي دعوى إعسار فور تحقق أي من الحالات المنصوص عليها في البند (2) من الفقرة (أ) من المادة (49) من القانون.\nد. تأدية أي مبالغ يقبضها أثناء تأدية مهامه إلى مستحقيها عند استحقاقها وفقا لأحكام القانون.\nهـ. اتخاذ الإجراءات المناسبة للمحافظة على سرية البيانات والمعلومات والوثائق والمستندات التي يحوزها وان يمتنع عن إفشائها إلا في حدود ما تستلزمه لتنفيذ مهامه وواجباته.","title":"واجبات وكيل الإعسار ومعيار العناية","memo":"⭐ يبذل الوكيل عناية الرجل المعتاد في ماله الخاص\n⭐ لا يوكل غيره بمهامه إلا بإذن أو تصريح المحكمة\n⭐ يتنحى فور تحقق حالات البند (2/أ) من المادة (49) من القانون","qs":[{"q":"ما معيار العناية المطلوب من وكيل الإعسار في تنفيذ التزاماته؟","o":["عناية الرجل المعتاد في ماله الخاص","بذل أقصى درجات العناية","عناية الوكيل بأجر المحددة في العقد","تحقيق نتيجة لصالح الدائنين"],"a":0},{"q":"يجوز لوكيل الإعسار أن يوكل لغيره مهام تتعلق بأعماله أو جزء منها:","o":["إذا أذنت أو صرحت له المحكمة بذلك","إذا وافقت لجنة الدائنين","إذا وافق المدين","في جميع الأحوال دون قيد"],"a":0},{"q":"متى يتنحى وكيل الإعسار عن دعوى الإعسار عند تحقق إحدى الحالات المنصوص عليها في المادة (49) من القانون؟","o":["فورا","خلال ثلاثين يوما","بعد موافقة لجنة الدائنين","عند انتهاء المرحلة التمهيدية"],"a":0}]},{"n":"22","chapter":"الفصل الثاني - ترخيص وكلاء الإعسار","notes":[],"source":"أ. على وكيل الإعسار الاحتفاظ بدفاتر وسجلات مستقلة منظمة حسب الأصول وعليه تدوين البيانات والمعلومات والوثائق الخاصة بكل دعوى إعسار وحفظها بشكل مستقل على أن تتضمن ما يلي:\n1. اسم المدين ورقمه الوطني أو الرقم الوطني للمنشأة حسب مقتضى الحال.\n2. نسخة من قرار إشهار الإعسار.\n3. سجلا مستقلا للوقائع والمعاملات اليومية المتعلقة بإجراءات الاعسار.\n4. المراسلات الخاصة بدعوى الإعسار.\n5. أي عقود أو اتفاقيات يبرمها للقيام بواجباته أو تنفيذ مهامه.\n6. قيودا محاسبية منظمة وفق معايير المحاسبة الدولية.\n7. البيانات المالية المدققة للمدين التي تتطلب التشريعات ذات العلاقة إعدادها.\n8. أي بيانات او وثائق تتعلق بدعوى الاعسار.\nب. يجوز إعداد وحفظ الدفاتر والسجلات بوسائل إلكترونية وفقا للتشريعات النافذة بهذا الخصوص.\nج. على وكيل الإعسار الاحتفاظ بالسجلات والدفاتر الواردة في هذه المادة لمدة لا تقل عن عشر سنوات من تاريخ انتهاء إجراءات الإعسار.\nد. على وكيل الإعسار أن يفتح حسابا بنكيا مستقلا لكل دعوى إعسار يتولاها وأن يزود المحكمة بتفاصيل الحساب ويلتزم بإيداع أي مبالغ يقبضها من أي جهة في ذلك الحساب وخلال مدة لا تتجاوز ثلاثة أيام من تاريخ قبضه لها وفي حال تخلفه عن ذلك تستحق عليه لذمة الإعسار فائدة تحتسب على أساس معدل أعلى فائدة تدفعها البنوك على الودائع بتاريخ وجوب الإيداع.\nهـ. على وكيل الإعسار أن يقدم لقاضي المحكمة التي تنظر دعوى الإعسار، في أول يوم عمل من كل شهر، كشف حساب شهري لكل حساب من الحسابات الخاصة بدعوى الاعسار تحت طائلة العزل.\nو. لوكيل الإعسار الاحتفاظ بمبلغ نقدي تحدده المحكمة على ألا يتجاوز خمسمائة دينار لاستخدامه للمصاريف النثرية وعليه توثيق المبالغ التي تم صرفها وفق الاصول والمعايير المعتمدة.","title":"دفاتر وسجلات وحسابات وكيل الإعسار","memo":"⭐ يحتفظ بدفاتر وسجلات مستقلة لكل دعوى لمدة لا تقل عن (10) سنوات من انتهاء الإجراءات\n⭐ قيود محاسبية وفق معايير المحاسبة الدولية\n⭐ حساب بنكي مستقل لكل دعوى، والإيداع خلال (3) أيام وإلا تستحق فائدة بأعلى معدل فائدة على الودائع\n⭐ كشف حساب شهري للقاضي أول يوم عمل من كل شهر تحت طائلة العزل؛ النثرية لا تتجاوز (500) دينار","qs":[{"q":"ما مدة احتفاظ وكيل الإعسار بالسجلات والدفاتر المتعلقة بدعوى الإعسار؟","o":["لا تقل عن عشر سنوات من تاريخ انتهاء إجراءات الإعسار","لا تقل عن خمس سنوات من تاريخ إشهار الإعسار","سبع سنوات من تاريخ انتهاء إجراءات الإعسار","خمس عشرة سنة من تاريخ إشهار الإعسار"],"a":0},{"q":"خلال أي مدة يلتزم وكيل الإعسار بإيداع المبالغ التي يقبضها في الحساب البنكي المستقل للدعوى؟","o":["مدة لا تتجاوز ثلاثة أيام من تاريخ قبضها","مدة لا تتجاوز سبعة أيام","مدة لا تتجاوز عشرة أيام","في أول يوم عمل من الشهر التالي"],"a":0},{"q":"ما الحد الأعلى للمبلغ النقدي الذي يجوز لوكيل الإعسار الاحتفاظ به للمصاريف النثرية؟","o":["خمسمائة دينار","ألف دينار","مائتان وخمسون دينارا","ألفا دينار"],"a":0},{"q":"تأخر وكيل إعسار عن تقديم كشف الحساب الشهري لقاضي المحكمة في أول يوم عمل من الشهر، فما الجزاء الذي نص عليه النظام؟","o":["العزل","غرامة مقدارها خمسمائة دينار","فائدة بأعلى معدل على الودائع","إنذار خطي من اللجنة"],"a":0}]},{"n":"23","chapter":"الفصل الثاني - ترخيص وكلاء الإعسار","notes":[],"source":"أ. على وكيل الإعسار الالتزام بقواعد سلوك مهنة وكيل الإعسار وآدابها ومعايير جودتها بما في ذلك ما يلي :\n1. الالتزام بالنزاهة والاستقامة وحسن التصرف في جميع تصرفاته وأعماله في الأوقات جميعها .\n2. تعريف نفسه للجهات التي يتعامل معها أثناء تأدية واجباته وإبراز صورة عن ترخيصه إذا طلب منه ذلك.\n3. الامتناع عن تقديم أي معلومات غير صحيحة أو مضللة لأي جهة والإفصاح عن المعلومات الضرورية التي تحتاجها الجهات التي يتعامل معها لغايات هذا التعامل.\n4. التعامل مع البيانات والمعلومات والوثائق والمستندات التي يحصل عليها اثناء أداء مهامه سواء من المدين أو الدائنين أو الغير بمنتهى السرية، واتخاذ الإجراءات المناسبة للمحافظة على سرية تلك البيانات والمعلومات والوثائق والمستندات.\n5. عدم طلب أو قبول أي عمولة أو أتعاب أو هدايا من أي جهة يتعامل معها أثناء تأدية مهامه باستثناء الأتعاب المقررة له بموجب أحكام القانون.\nب. تعتمد اللجنة قواعد سلوك مهنة وكلاء الإعسار وآدابها ومعايير جودتها بموجب تعليمات تصدرها لهذه الغاية.","title":"قواعد سلوك مهنة وكيل الإعسار","memo":"⭐ الالتزام بالنزاهة والاستقامة، وتعريف نفسه وإبراز صورة ترخيصه إذا طلب\n⭐ عدم تقديم معلومات مضللة والمحافظة على السرية\n⭐ عدم طلب أو قبول عمولة أو أتعاب أو هدايا باستثناء الأتعاب المقررة بموجب القانون\n⭐ تعتمد اللجنة قواعد السلوك بتعليمات","qs":[{"q":"يجوز لوكيل الإعسار أن يقبض من الجهات التي يتعامل معها أثناء تأدية مهامه:","o":["الأتعاب المقررة له بموجب أحكام القانون فقط","الهدايا الرمزية","العمولات المتفق عليها مع الدائنين","أي أتعاب توافق عليها لجنة الدائنين"],"a":0},{"q":"كيف تعتمد قواعد سلوك مهنة وكلاء الإعسار وآدابها ومعايير جودتها؟","o":["بموجب تعليمات تصدرها لجنة وكلاء الإعسار","بنظام يصدره مجلس الوزراء","بقرار من المحكمة","بتعليمات يصدرها المراقب"],"a":0},{"q":"أي مما يلي لا يعد من قواعد سلوك مهنة وكيل الإعسار الواردة في النظام؟","o":["الإفصاح للعموم عن البيانات التي حصل عليها من المدين","تعريف نفسه للجهات التي يتعامل معها وإبراز صورة ترخيصه إذا طلب منه","الامتناع عن تقديم أي معلومات غير صحيحة أو مضللة","الالتزام بالنزاهة والاستقامة وحسن التصرف"],"a":0}]},{"n":"24","chapter":"الفصل الثاني - ترخيص وكلاء الإعسار","notes":[],"source":"أ. للجنة الطلب من وكلاء الاعسار تصويب اوضاعهم خلال مدة محددة اذا ثبت لها أي مما يلي :\n1. أن وكيل الاعسار خالف أحكام القانون او الأنظمة او التعليمات او قواعد سلوك وآداب المهنة او القرارات الصادرة عن اللجنة.\n2. أن وكيل الاعسار قد فقد أيا من الشروط التي تم ترخيصه بموجبها.\n3. أن البيانات او الأوراق الثبوتية او الشهادات التي اعتمدت لترخيص وكيل الإعسار غير صحيحة.\n4. أن وكيل الاعسار ارتكب جرم إساءة الائتمان او الاحتيال فيما يتعلق بالأموال المحفوظة لديه سواء أكانت عائدة للمدين او للغير.\n5. انتهاء ترخيص وكيل الإعسار دون تجديده وفقا لأحكام هذا النظام والتعليمات الصادرة بموجبه وما زال يمارس اعماله.\nب. إذا لم يقم وكيل الاعسار بتصويب أوضاعه وفقا لأحكام الفقرة (أ) من هذه المادة، فللجنة تعليق ترخيصه أو الغاؤه وشطبه من قائمة وكلاء الاعسار .\nج. إذا أصدرت اللجنة قرارا بإلغاء ترخيص وكيل الإعسار، فلا يجوز له التقدم بطلب ترخيص جديد لممارسة أعماله قبل مضي ثلاث سنوات من تاريخ صدور قرار بإلغاء الترخيص.\nد. تبلغ القرارات الصادرة عن اللجنة وفقا لأحكام هذه المادة الى المحاكم التي يتولى فيها وكيل الاعسار دعاوى وعلى المحكمة عزله وتعيين بديل عنه.\nهـ. للجنة إحالة وكيل الاعسار في حال ارتكابه أيا من الأفعال التي تشكل جريمة الى الجهة التحقيقية المختصة لملاحقته وفقا لأحكام القوانين النافذة.","title":"تصويب الأوضاع وإلغاء الترخيص","memo":"⭐ للجنة طلب تصويب الأوضاع خلال مدة محددة عند المخالفة أو فقدان الشروط أو عدم صحة الوثائق أو إساءة الائتمان أو الممارسة بترخيص منتهٍ\n⭐ عند عدم التصويب: تعليق الترخيص أو إلغاؤه والشطب\n⭐ لا يجوز التقدم بطلب ترخيص جديد قبل مضي (3) سنوات من قرار الإلغاء\n⭐ تبلغ القرارات للمحاكم وعليها عزل الوكيل وتعيين بديل","qs":[{"q":"بعد إلغاء ترخيص وكيل الإعسار، لا يجوز له التقدم بطلب ترخيص جديد قبل مضي:","o":["ثلاث سنوات من تاريخ صدور قرار الإلغاء","سنتين من تاريخ صدور قرار الإلغاء","خمس سنوات من تاريخ صدور قرار الإلغاء","سنة واحدة من تاريخ صدور قرار الإلغاء"],"a":0},{"q":"إذا لم يقم وكيل الإعسار بتصويب أوضاعه خلال المدة المحددة، فللجنة:","o":["تعليق ترخيصه أو إلغاؤه وشطبه من قائمة وكلاء الإعسار","فرض غرامة مالية عليه","إحالته إلى المحكمة لعزله فقط","تمديد مدة التصويب مرة ثانية"],"a":0},{"q":"عند تبليغ المحكمة بقرار اللجنة بشأن وكيل إعسار يتولى دعاوى لديها، فعلى المحكمة:","o":["عزله وتعيين بديل عنه","وقف دعوى الإعسار","الاستمرار به إلى حين انتهاء الدعوى","إحالته إلى الجهة التحقيقية"],"a":0}]},{"n":"25","chapter":"الفصل الثاني - ترخيص وكلاء الإعسار","notes":[],"source":"للجنة تكليف موظف أو أكثر من موظفي الوحدة أو أي خبير من أي جهة خارجية لتدقيق دفاتر وكيل الإعسار وسجلاته وعلى وكيل الإعسار ان يتعاون معهم لتمكينهم من إنجاز مهمتهم وان يضع \" تصرفهم ما يطلبونه من وثائق وأوراق وسجلات وكشوفات بشكل كامل، وعلى وكيل الإعسار الاستجابة لطلب اللجنة او من تكلفه لسماع أقواله حول المسائل التي تحددها اللجنة وخلال الفترة الزمنية المحددة من قبلها.","title":"تدقيق دفاتر وكيل الإعسار","memo":"⭐ للجنة تكليف موظف أو أكثر من الوحدة أو خبير من جهة خارجية لتدقيق دفاتر وكيل الإعسار وسجلاته\n⭐ على الوكيل التعاون ووضع الوثائق تحت تصرفهم والاستجابة لسماع أقواله خلال المدة المحددة من اللجنة","qs":[{"q":"من له صلاحية تكليف موظفين أو خبير خارجي لتدقيق دفاتر وكيل الإعسار وسجلاته؟","o":["لجنة وكلاء الإعسار","المحكمة المختصة","لجنة الدائنين","المسجل"],"a":0},{"q":"يجوز تكليف تدقيق دفاتر وكيل الإعسار وسجلاته لـ:","o":["موظف أو أكثر من موظفي الوحدة أو أي خبير من أي جهة خارجية","موظفي المحكمة فقط","أعضاء لجنة الدائنين","مدقق حسابات المدين"],"a":0}]},{"n":"27","chapter":"الفصل الثاني - ترخيص وكلاء الإعسار","notes":[],"source":"أ. ينشأ لدى الدائرة حساب أمانات يسمى \"حساب نفقات حالات الإعسار بلا أموال\".\nب. يستخدم رصيد الحساب لتغطية النفقات الناشئة عن دعاوى الإعسار التي تقرر المحكمة عدم وجود أموال كافية لتغطية نفقاتها وعلى النحو التالي:\n1. أتعاب الخبرة .\n2. أي نفقات ومصاريف قضائية لازمة للسير في دعوى الإعسار.\n3. أتعاب وكيل الإعسار التي تحددها المحكمة.\nج. تعفى دعوى الإعسار من رسوم المحاكم بأنواعها كافة ودرجاتها بما فيها رسوم الإبراز .\nد. تعفى دعوى الإعسار ومعاملات الصرف من الحساب المنصوص عليه في الفقرة (أ) من هذه المادة من رسوم طوابع الواردات.","title":"حساب نفقات حالات الإعسار بلا أموال","memo":"⭐ ينشأ لدى الدائرة حساب أمانات يسمى (حساب نفقات حالات الإعسار بلا أموال)\n⭐ يغطي: أتعاب الخبرة، والنفقات القضائية اللازمة، وأتعاب وكيل الإعسار التي تحددها المحكمة\n⭐ تعفى دعوى الإعسار من رسوم المحاكم كافة بما فيها رسوم الإبراز، ومن رسوم طوابع الواردات","qs":[{"q":"أين ينشأ (حساب نفقات حالات الإعسار بلا أموال)؟","o":["لدى دائرة مراقبة الشركات","لدى وزارة المالية","لدى المحكمة المختصة","لدى البنك المركزي"],"a":0},{"q":"أي مما يلي لا يغطى من رصيد حساب نفقات حالات الإعسار بلا أموال؟","o":["ديون الدائنين غير المضمونة","أتعاب الخبرة","النفقات والمصاريف القضائية اللازمة للسير في الدعوى","أتعاب وكيل الإعسار التي تحددها المحكمة"],"a":0},{"q":"ما حكم رسوم المحاكم على دعوى الإعسار وفق النظام؟","o":["تعفى من رسوم المحاكم بأنواعها كافة ودرجاتها بما فيها رسوم الإبراز","تستوفى بنصف قيمتها","تعفى من رسوم الدرجة الأولى فقط","تستوفى من حساب نفقات حالات الإعسار بلا أموال"],"a":0}]},{"n":"28","chapter":"الفصل الثالث - حساب نفقات حالات الإعسار بلا أموال","notes":[],"source":"أ. تتم تغذية الحساب من المصادر المحددة في المادة (112) من القانون وعلى النحو التالي:\n1. ما يخصصه مجلس الوزراء سنويا من حساب الموازنة العامة .\n2. ما نسبته (1) من الرسوم المقررة على تسجيل الشركات بأنواعها وأشكالها كافة.\n3. ما نسبته (1) من الرسوم المقررة على تسجيل المؤسسات الفردية المستحقة وفقا لأحكام قانون التجارة وقانون الصناعة والتجارة والأنظمة الصادرة بموجبهما.\n4. ما نسبته (10) من الرسوم المستحقة على ترخيص وكلاء الإعسار المبينة في المادة (26) من هذا النظام.\n5. ما نسبته (5) من الأتعاب التي تقرر المحكمة صرفها لوكيل الإعسار.\nب. لا تدخل في احتساب الرسوم المبينة أعلاه رسوم الطوابع التي تستوفى عند التسجيل.","title":"مصادر تغذية حساب النفقات","memo":"⭐ ما يخصصه مجلس الوزراء سنويا من الموازنة العامة\n⭐ (1%) من رسوم تسجيل الشركات و(1%) من رسوم تسجيل المؤسسات الفردية\n⭐ (10%) من رسوم ترخيص وكلاء الإعسار، و(5%) من الأتعاب التي تقرر المحكمة صرفها لوكيل الإعسار\n⭐ لا تدخل رسوم الطوابع المستوفاة عند التسجيل في الاحتساب","qs":[{"q":"ما النسبة التي تؤول إلى حساب نفقات حالات الإعسار بلا أموال من الرسوم المستحقة على ترخيص وكلاء الإعسار؟","o":["%10","%5","%1","%50"],"a":0},{"q":"ما النسبة التي تؤول إلى الحساب من الأتعاب التي تقرر المحكمة صرفها لوكيل الإعسار؟","o":["%5","%10","%1","%2"],"a":0},{"q":"ما النسبة التي تؤول إلى الحساب من الرسوم المقررة على تسجيل الشركات بأنواعها؟","o":["%1","%5","%10","%3"],"a":0},{"q":"عند احتساب النسب المقتطعة من رسوم تسجيل الشركات والمؤسسات الفردية لصالح الحساب:","o":["لا تدخل رسوم الطوابع التي تستوفى عند التسجيل","تدخل رسوم الطوابع كاملة","تدخل نصف رسوم الطوابع","يحدد مجلس الوزراء ما يدخل منها سنويا"],"a":0}]},{"n":"29","chapter":"الفصل الثالث - حساب نفقات حالات الإعسار بلا أموال","notes":[],"source":"أ. يتم إدارة حساب نفقات حالات الإعسار بلا أموال من قبل اللجنة ووفقا للأنظمة المالية والتعليمات المعمول بها لدى الوزارة ويتم الصرف من الحساب بموجب قرار يصدر عن المحكمة التي تنظر دعوى الإعسار.\nب. يحدد الحد الأدنى لأتعاب وكلاء الاعسار في حالات الإعسار بدون أموال بشكل سنوي بقرار يصدر عن اللجنة في موعد لا يتجاوز اليوم الثلاثين من شهر تشرين الثاني من السنة السابقة.","title":"إدارة حساب النفقات والحد الأدنى للأتعاب","memo":"⭐ تدير اللجنة الحساب وفق الأنظمة المالية والتعليمات المعمول بها لدى الوزارة\n⭐ يتم الصرف بقرار من المحكمة التي تنظر دعوى الإعسار\n⭐ الحد الأدنى لأتعاب الوكلاء في حالات الإعسار بدون أموال يحدد سنويا بقرار من اللجنة في موعد لا يتجاوز (30) تشرين الثاني من السنة السابقة","qs":[{"q":"من يدير حساب نفقات حالات الإعسار بلا أموال؟","o":["لجنة وكلاء الإعسار","المحكمة المختصة","وزارة المالية","المسجل"],"a":0},{"q":"يتم الصرف من حساب نفقات حالات الإعسار بلا أموال بموجب قرار يصدر عن:","o":["المحكمة التي تنظر دعوى الإعسار","لجنة وكلاء الإعسار","الوزير","المراقب"],"a":0},{"q":"ما الموعد الأقصى لصدور قرار تحديد الحد الأدنى لأتعاب وكلاء الإعسار في حالات الإعسار بدون أموال؟","o":["اليوم الثلاثون من شهر تشرين الثاني من السنة السابقة","اليوم الأول من شهر كانون الثاني من كل سنة","اليوم الحادي والثلاثون من شهر كانون الأول من السنة السابقة","اليوم الثلاثون من شهر حزيران من كل سنة"],"a":0}]},{"n":"30","chapter":"الفصل الثالث - حساب نفقات حالات الإعسار بلا أموال","notes":[],"source":"أ. تشكل المحكمة لجنة للدائنين إذا زاد عددهم على الخمسين ، على أنه يجوز للمحكمة عدم تشكيل لجنة الدائنين إذا رأت أن ذلك لا يحقق مصلحة إجراءات الإعسار، ولها ان تعزل أيا من أعضائها وتستبدل غيره به إذا وجدت سببا مبررا لذلك.\nب. مع مراعاة الإجراءات المبينة في المواد (44) و(45) و (46) و (47) من القانون، يتم اختيار أعضاء لجنة الدائنين من بين مختلف فئات دائني الإعسار كلما كان ذلك ممكنا وعلى النحو التالي:\n1. دائن واحد على الأقل من الدائنين أصحاب الديون الممتازة يتم اختياره منهم بالأغلبية المطلقة لديونهم بإشراف وكيل الاعسار .\n2. دائن واحد على الأقل من أصحاب الديون غير المضمونة يتم اختياره منهم بالأغلبية المطلقة لديونهم بإشراف وكيل الإعسار .\n3. دائن واحد أو اكثر من أصحاب الديون المضمونة يتم اختياره منهم بالأغلبية المطلقة لديونه شريطة أن لا يشكلوا أغلبية الأصوات فيها.\n4. أحد العاملين لدى المدين اذا تجاوز عددهم عشرين عاملا يتم اختياره منهم بالأغلبية المطلقة لديونهم بإشراف وكيل الإعسار شريطة عدم احقيته في التصويت على المسائل التي تناقشها اللجنة.\nج. إذا كان الدائن شخصا اعتباريا فيمثله في لجنة الدائنين شخص طبيعي بموجب تفويض خطي.\nد. مع مراعاة أحكام الفقرة (ب) من هذه المادة، لأي من الأشخاص الذين تم تعيينهم في لجنة الدائنين الاعتراض لدى المحكمة على تعيينه خلال مدة عشرة أيام من تاريخ تبلغه بالقرار،","title":"تشكيل لجنة الدائنين","memo":"⭐ تشكل المحكمة لجنة للدائنين إذا زاد عددهم على (50)، ولها عدم تشكيلها إن لم تحقق المصلحة\n⭐ يختار الأعضاء بالأغلبية المطلقة لديون كل فئة: دائن ممتاز، ودائن غير مضمون، ودائن مضمون أو أكثر (دون أن يشكلوا الأغلبية)\n⭐ يمثل العاملين أحدهم إذا تجاوز عددهم (20) عاملا دون حق التصويت\n⭐ الشخص الاعتباري يمثله شخص طبيعي بتفويض خطي، والاعتراض على التعيين خلال (10) أيام من التبلغ","qs":[{"q":"متى تشكل المحكمة لجنة للدائنين؟","o":["إذا زاد عدد الدائنين على الخمسين","إذا زاد عدد الدائنين على العشرين","إذا زاد عدد الدائنين على المائة","في جميع دعاوى الإعسار دون استثناء"],"a":0},{"q":"يمثل العاملين لدى المدين في لجنة الدائنين أحدهم إذا تجاوز عددهم:","o":["عشرين عاملا، دون أن يكون له حق التصويت","خمسين عاملا، مع حق التصويت","عشرة عمال، مع حق التصويت","مائة عامل، دون حق التصويت"],"a":0},{"q":"ما المدة المتاحة لمن تم تعيينه في لجنة الدائنين للاعتراض لدى المحكمة على تعيينه؟","o":["عشرة أيام من تاريخ تبلغه بالقرار","خمسة أيام من تاريخ صدور القرار","ثلاثون يوما من تاريخ تبلغه بالقرار","سبعة أيام من تاريخ صدور القرار"],"a":0},{"q":"يشترط في أعضاء لجنة الدائنين من أصحاب الديون المضمونة:","o":["ألا يشكلوا أغلبية الأصوات فيها","أن يكون عددهم ثلاثة على الأقل","أن يكون أحدهم رئيسا للجنة","أن تزيد ديونهم على نصف ديون الإعسار"],"a":0}]},{"n":"31","chapter":"الفصل الرابع - شروط لجنة الدائنين واجراءاتها - وللمحكمة بعد النظر في الاعتراض ان تستبدل غيره به .","notes":[],"source":"يشترط في عضو لجنة الدائنين ما يلي:\nأ. أن لا يكون دائنا ذا صلة بالمدين بالمعنى المنصوص عليه في المادة (4) من القانون.\nب. أن لا يكون من الدائنين الأدنى في مرتبة الأولوية المنصوص عليهم في المادة (41) من القانون.\nج. أن لا يكون من المساهمين او الشركاء في المدين إذا كان شخصا اعتباريا.\nد. ان لا يكون من أصحاب الديون المتنازع عليها المنصوص عليهم في المادة (46) من القانون ما لم تقرر المحكمة خلاف ذلك.\nهـ. ان لا يكون الدائن او ممثله محكوما بأي عقوبة جنائية أو جنحية في جريمة مخلة بالشرف كالرشوة والاختلاس والسرقة والتزوير واساءة الائتمان والشهادة الكاذبة أو أي جريمة أخرى مخلة بالآداب والأخلاق العامة، أو أن يكون فاقدا الأهلية المدنية أو محكوما بالإفلاس الاحتيالي أو بأي عقوبة من العقوبات المنصوص عليها في المادتين (113) و(114) من القانون.","title":"شروط عضو لجنة الدائنين","memo":"⭐ ألا يكون دائنا ذا صلة بالمدين (م4 من القانون)\n⭐ ألا يكون من الدائنين الأدنى مرتبة (م41)، ولا مساهما أو شريكا في المدين الاعتباري\n⭐ ألا يكون صاحب دين متنازع عليه (م46) ما لم تقرر المحكمة خلاف ذلك\n⭐ ألا يكون محكوما بجريمة مخلة بالشرف أو فاقد الأهلية أو محكوما بالإفلاس الاحتيالي","qs":[{"q":"أي مما يلي يجوز أن يكون عضوا في لجنة الدائنين بقرار من المحكمة رغم وجود مانع أصلي؟","o":["صاحب دين متنازع عليه","دائن ذو صلة بالمدين","مساهم أو شريك في المدين الاعتباري","دائن محكوم بالإفلاس الاحتيالي"],"a":0},{"q":"أي مما يلي لا يعد مانعا من عضوية لجنة الدائنين؟","o":["أن يكون الدائن من أصحاب الديون غير المضمونة","أن يكون من الدائنين الأدنى في مرتبة الأولوية","أن يكون من المساهمين أو الشركاء في المدين الاعتباري","أن يكون فاقدا الأهلية المدنية"],"a":0},{"q":"دائن لشركة معسرة هو في الوقت ذاته شريك فيها، فما حكم عضويته في لجنة الدائنين؟","o":["لا يجوز أن يكون عضوا","يجوز إذا كان دينه مضمونا","يجوز بموافقة وكيل الإعسار","يجوز دون حق التصويت"],"a":0}]},{"n":"32","chapter":"الفصل الرابع - شروط لجنة الدائنين واجراءاتها - وللمحكمة بعد النظر في الاعتراض ان تستبدل غيره به .","notes":[],"source":"أ. تنتخب لجنة الدائنين من بين أعضائها رئيسا من أصحاب الديون غير المضمونة ونائبا له يقوم بمهام الرئيس وصلاحياته عند غيابه.\nب. تعين لجنة الدائنين أمين سر للجنة من بين أعضائها يتولى تنظيم اجتماعاتها وإعداد جداول أعمالها وتدوين محاضر جلساتها وقراراتها.\nج. على رئيس اللجنة تزويد المحكمة ووكيل الإعسار بنسخ من قراراتها خلال ثلاثة أيام من صدورها.\nد. يعتبر رئيس لجنة الدائنين ممثلا للجنة في مواجهة الغير وأمام المحكمة ووكيل الإعسار وأي جهة إدارية وقضائية لغايات تنفيذ قرارات اللجنة الصادرة بموجب الصلاحيات الممنوحة لها بموجب أحكام القانون وهذا النظام، وله بهذه الصفة التوقيع نيابة عن اللجنة شريطة ان لا يتجاوز حدود صلاحياته التي تقررها اللجنة.\nهـ. لا يتقاضى أعضاء لجنة الدائنين أي رواتب أو مزايا أو بدلات عضوية .\nو. لا يجوز للجنة الدائنين أن تتكبد أي نفقات نيابة عن ذمة الإعسار إلا بموافقة المحكمة وبتنسيب من وكيل الإعسار.\nز. لا يجوز لرئيس لجنة الدائنين أو لأي من أعضائها القيام بأي عمل أو تصرف لصالح ذمة الإعسار مقابل أجر أو تعويض أو مكافأة إلا بموافقة المحكمة.\nح. يحظر على رئيس لجنة الدائنين أو أي من أعضائها إفشاء أي معلومات أو بيانات تتعلق بذمة الإعسار حصل عليها بحكم عضويته في اللجنة وذلك تحت طائلة عزله من اللجنة ومطالبته بالتعويض عن الضرر الذي لحق بذمة الإعسار من جراء هذا الافشاء.\nط. يعتبر أعضاء لجنة الدائنين مسؤولين بالتكافل والتضامن تجاه الدائنين والغير عن كل مخالفة يرتكبها أي منهم أو جميعهم للقوانين والأنظمة المعمول بها ولهذا النظام وعن تقصيرهم وإهمالهم في تنفيذ المهام المناطة بهم بموجب أحكام القانون وهذا النظام والقرارات التي تصدر عن المحكمة.","title":"تنظيم لجنة الدائنين وواجبات أعضائها","memo":"⭐ تنتخب اللجنة رئيسا من أصحاب الديون غير المضمونة ونائبا له، وتعين أمين سر من بين أعضائها\n⭐ يزود الرئيس المحكمة ووكيل الإعسار بنسخ القرارات خلال (3) أيام\n⭐ لا يتقاضى الأعضاء رواتب أو بدلات، ولا تتكبد اللجنة نفقات إلا بموافقة المحكمة وتنسيب وكيل الإعسار\n⭐ الأعضاء مسؤولون بالتكافل والتضامن؛ والإفشاء يعرض العضو للعزل والتعويض","qs":[{"q":"يشترط في رئيس لجنة الدائنين أن يكون من:","o":["أصحاب الديون غير المضمونة","أصحاب الديون المضمونة","أصحاب الديون الممتازة","العاملين لدى المدين"],"a":0},{"q":"خلال أي مدة يزود رئيس لجنة الدائنين المحكمة ووكيل الإعسار بنسخ من قرارات اللجنة؟","o":["ثلاثة أيام من صدورها","سبعة أيام من صدورها","عشرة أيام من صدورها","يوم واحد من صدورها"],"a":0},{"q":"لا يجوز للجنة الدائنين أن تتكبد أي نفقات نيابة عن ذمة الإعسار إلا:","o":["بموافقة المحكمة وبتنسيب من وكيل الإعسار","بموافقة الأغلبية المطلقة لأعضائها","بموافقة لجنة وكلاء الإعسار","بموافقة المدين"],"a":0},{"q":"ما طبيعة مسؤولية أعضاء لجنة الدائنين تجاه الدائنين والغير عن المخالفات والتقصير؟","o":["مسؤولية بالتكافل والتضامن","مسؤولية فردية لكل عضو عن فعله فقط","مسؤولية الرئيس وحده","لا مسؤولية عليهم لأنهم لا يتقاضون أجرا"],"a":0}]},{"n":"33","chapter":"الفصل الرابع - شروط لجنة الدائنين واجراءاتها - وللمحكمة بعد النظر في الاعتراض ان تستبدل غيره به .","notes":[],"source":"أ. تجتمع لجنة الدائنين بدعوة من رئيسها أو نائبه في حال غيابه أو بطلب خطي يقدمه لرئيس اللجنة اثنان من أعضائها أو بناء على طلب وكيل الإعسار على أن يتضمن الطلب في الأحوال جميعها الأسباب الداعية لعقد الاجتماع، وإذا لم يوجه رئيس اللجنة أو نائبه الدعوة إلى الاجتماع خلال ثلاثة أيام من تاريخ تسلمه الطلب فللأعضاء الذين قدموا الطلب أو وكيل الاعسار او المحكمة دعوة اللجنة للاجتماع.\nب. تعقد لجنة الدائنين اجتماعاتها بحضور الأغلبية المطلقة لأعضائها في المكان والزمان المبينين في الدعوة.\nج. تصدر لجنة الدائنين قراراتها بالأغلبية المطلقة لأعضائها الذين حضروا الاجتماع وإذا تساوت الأصوات يرجح الجانب الذي صوت معه رئيس الاجتماع.\nد. يكون التصويت على قرارات لجنة الدائنين شخصيا ويقوم به العضو نفسه ولا يجوز التوكيل فيه.\nهـ. يجوز للجنة الدائنين عقد اجتماعاتها بواسطة الهاتف او بأي من وسائل الاتصال الأخرى شريطة ان يتمكن الاعضاء المشاركون جميعهم في الاجتماع من سماع ومناقشة بعضهم البعض حول جدول أعمال الاجتماع وعلى ان يصادق رئيس اللجنة وأمين السر على المحضر.\nو. يعتبر أي محضر او شهادة او قرار صادر عن رئيس لجنة الدائنين أو نائبه في حال غيابه ومصدق عليه من قبل أمين السر دليلا على صحة هذه القرارات ويتحمل الرئيس ونائبه وأمين السر مسؤولية أي شهادة تصدر عنهم في هذا الخصوص.","title":"اجتماعات لجنة الدائنين وقراراتها","memo":"⭐ تجتمع بدعوة رئيسها أو نائبه، أو بطلب خطي من عضوين، أو بطلب وكيل الإعسار\n⭐ إذا لم يدع الرئيس خلال (3) أيام فللطالبين أو وكيل الإعسار أو المحكمة الدعوة\n⭐ النصاب: الأغلبية المطلقة للأعضاء، والقرارات بالأغلبية المطلقة للحاضرين ويرجح جانب رئيس الاجتماع عند التساوي\n⭐ التصويت شخصي ولا يجوز التوكيل؛ ويجوز الاجتماع بالهاتف أو وسائل الاتصال","qs":[{"q":"كم عدد أعضاء لجنة الدائنين الذين يحق لهم تقديم طلب خطي لعقد اجتماع للجنة؟","o":["اثنان","ثلاثة","الأغلبية المطلقة","خمسة"],"a":0},{"q":"إذا لم يوجه رئيس لجنة الدائنين الدعوة للاجتماع خلال المدة المحددة بعد تسلم الطلب، فما هذه المدة؟","o":["ثلاثة أيام من تاريخ تسلمه الطلب","سبعة أيام","عشرة أيام","خمسة أيام"],"a":0},{"q":"أراد عضو في لجنة الدائنين توكيل عضو آخر بالتصويت عنه لسفره، فما حكم ذلك؟","o":["لا يجوز؛ فالتصويت شخصي يقوم به العضو نفسه","يجوز بتوكيل خطي","يجوز بموافقة رئيس اللجنة","يجوز بموافقة المحكمة"],"a":0},{"q":"ما النصاب اللازم لعقد اجتماع لجنة الدائنين؟","o":["حضور الأغلبية المطلقة لأعضائها","حضور ثلثي أعضائها","حضور خمسة أعضاء على الأقل","حضور جميع الأعضاء"],"a":0}]},{"n":"34","chapter":"الفصل الرابع - شروط لجنة الدائنين واجراءاتها - وللمحكمة بعد النظر في الاعتراض ان تستبدل غيره به .","notes":[],"source":"مع مراعاة أحكام المادة (30) من هذا النظام، إذا شغر مركز عضو في لجنة الدائنين لأي سبب من الأسباب فيخلفه عضو تعينه المحكمة وفقا لأحكام هذا النظام","title":"شغور العضوية في لجنة الدائنين","memo":"⭐ إذا شغر مركز عضو في لجنة الدائنين لأي سبب يخلفه عضو تعينه المحكمة، مع مراعاة المادة (30)","qs":[{"q":"إذا شغر مركز عضو في لجنة الدائنين، فمن يعين من يخلفه؟","o":["المحكمة","لجنة الدائنين","وكيل الإعسار","الهيئة العامة للدائنين"],"a":0},{"q":"استقال عضو يمثل الدائنين أصحاب الديون الممتازة من لجنة الدائنين، فكيف يتم ملء مركزه؟","o":["يخلفه عضو تعينه المحكمة مع مراعاة أحكام تشكيل اللجنة الواردة في المادة (30)","يبقى المركز شاغرا حتى انتهاء إجراءات الإعسار","يعين رئيس لجنة الدائنين بديلا عنه","ينتخب الدائنون غير المضمونين بديلا عنه"],"a":0}]},{"n":"35","chapter":"الفصل الرابع - شروط لجنة الدائنين واجراءاتها - وللمحكمة بعد النظر في الاعتراض ان تستبدل غيره به .","notes":[],"source":"مع مراعاة أحكام المادة (53) من القانون تحدد المحكمة أتعاب وكيل الإعسار وتقسم الى أتعاب ثابتة وأتعاب متغيرة تعتمد على تحقيق نتيجة.","title":"تحديد أتعاب وكيل الإعسار","memo":"⭐ تحدد المحكمة أتعاب وكيل الإعسار مع مراعاة المادة (53) من القانون\n⭐ تقسم إلى أتعاب ثابتة وأتعاب متغيرة تعتمد على تحقيق نتيجة","qs":[{"q":"تقسم أتعاب وكيل الإعسار التي تحددها المحكمة إلى:","o":["أتعاب ثابتة وأتعاب متغيرة تعتمد على تحقيق نتيجة","أتعاب شهرية وأتعاب نهائية","أتعاب مقطوعة فقط","أتعاب إدارية وأتعاب قضائية"],"a":0},{"q":"من الجهة التي تحدد أتعاب وكيل الإعسار؟","o":["المحكمة","لجنة وكلاء الإعسار","لجنة الدائنين","الهيئة العامة للدائنين"],"a":0}]},{"n":"36","chapter":"الفصل الرابع - شروط لجنة الدائنين واجراءاتها - وللمحكمة بعد النظر في الاعتراض ان تستبدل غيره به .","notes":[],"source":"أ. تحدد المحكمة نسبة أتعاب وكيل الإعسار الثابتة بشكل مبدئي في قرار إشهار الإعسار وفقا للنسب المنصوص عليها في جدول الأتعاب الملحق بهذا النظام، ولهذه الغاية تعتمد المحكمة الحد الأدنى من نسبة الأتعاب للشريحة التي يندرج تحتها صافي قيمة ذمة الإعسار المبينة في جدول الأتعاب على ان يتم اعتماد القيمة الإجمالية النهائية للمبالغ القابلة للتوزيع على الدائنين وفقا لأحكام المادة (38) والمادة (106) من القانون عند تحديد قيمة الأتعاب النهائية الثابتة المستحقة لوكيل الإعسار.\nب. للمحكمة أن تعتمد نسبة أعلى من النسبة التي اعتمدتها في قرار إشهار الإعسار عند التحديد النهائي للأتعاب الثابتة لوكيل الإعسار شريطة ان لا تتجاوز الحد الأعلى للنسبة المبينة في جدول الأتعاب مراعية الجهد المبذول من وكيل الإعسار في إدارة ملف دعوى الإعسار وبالتحديد:\n1. وجود خطة إعادة تنظيم متفق عليها مسبقا.\n2. عدد الدائنين.\n3. عدد العاملين لدى المدين.\n4. استمرار النشاط الاقتصادي للمدين.\n5. عدد فروع المدين أو وحدات النشاط الاقتصادي أو المنشآت العائدة له .\n6. بيع وحدات النشاط بصفتها عاملة ومنتجة.\nج. للمحكمة أن تقرر صرف دفعات مقدمة في حساب أتعاب وكيل الإعسار الثابتة شريطة ان لا تتجاوز الاتعاب المصروفة ما نسبته (50) من إجمالي الأتعاب المقررة ويتم صرف الباقي عند التوزيع النهائي لمتحصلات ذمة الإعسار.","title":"الأتعاب الثابتة لوكيل الإعسار","memo":"⭐ تحدد المحكمة النسبة مبدئيا في قرار الإشهار بالحد الأدنى لنسبة الشريحة في جدول الأتعاب\n⭐ عند التحديد النهائي يجوز اعتماد نسبة أعلى دون تجاوز الحد الأعلى مراعاة للجهد (خطة متفق عليها، عدد الدائنين والعاملين، استمرار النشاط، الفروع، البيع كوحدات عاملة)\n⭐ الدفعات المقدمة لا تتجاوز (50%) من إجمالي الأتعاب والباقي عند التوزيع النهائي","qs":[{"q":"عند التحديد المبدئي لنسبة الأتعاب الثابتة في قرار إشهار الإعسار، تعتمد المحكمة:","o":["الحد الأدنى من نسبة الأتعاب للشريحة التي يندرج تحتها صافي قيمة ذمة الإعسار","الحد الأعلى من نسبة الأتعاب للشريحة","متوسط الحدين الأدنى والأعلى","نسبة تتفق عليها مع لجنة الدائنين"],"a":0},{"q":"ما الحد الأقصى للدفعات المقدمة التي يجوز صرفها من الأتعاب الثابتة لوكيل الإعسار؟","o":["%50 من إجمالي الأتعاب المقررة","%25 من إجمالي الأتعاب المقررة","%10 من إجمالي الأتعاب المقررة","%75 من إجمالي الأتعاب المقررة"],"a":0},{"q":"أي مما يلي لا يعد من المعايير التي تراعيها المحكمة لاعتماد نسبة أعلى للأتعاب الثابتة؟","o":["عدد سنوات خبرة وكيل الإعسار","عدد الدائنين","عدد العاملين لدى المدين","وجود خطة إعادة تنظيم متفق عليها مسبقا"],"a":0}]},{"n":"37","chapter":"الفصل الخامس - معايير تقدير أتعاب وكلاء الإعسار","notes":[],"source":"أ. تضمن المحكمة قرار إشهار الإعسار استحقاق أتعاب متغيرة لوكيل الإعسار تعتمد على تحقيق نتيجة على ان تسدد عند انتهاء اجراءات الاعسار .\nب. تحدد المحكمة قيمة الأتعاب المتغيرة المستحقة لوكيل الاعسار عند انتهاء إجراءات الاعسار بناء على المبالغ التي تم استردادها لصالح ذمة الاعسار من خلال إجراءات عدم نفاذ التصرفات المقامة وفقا لأحكام القانون او المبالغ المحصلة بموجب احكام صادرة بالمسؤولية الشخصية لمديري المدين، إذا كان شخصا اعتباريا.\nج. في الأحوال كافة لا يجوز أن تتجاوز أتعاب وكيل الإعسار المتغيرة التي تعتمد على تحقيق نتيجة ما نسبته (10) من صافي المبالغ المحصلة.","title":"الأتعاب المتغيرة لوكيل الإعسار","memo":"⭐ يتضمن قرار الإشهار استحقاق أتعاب متغيرة تسدد عند انتهاء إجراءات الإعسار\n⭐ تحدد بناء على المبالغ المستردة بإجراءات عدم نفاذ التصرفات أو المحصلة بأحكام المسؤولية الشخصية لمديري المدين\n⭐ لا تتجاوز في الأحوال كافة (10%) من صافي المبالغ المحصلة","qs":[{"q":"ما الحد الأعلى للأتعاب المتغيرة لوكيل الإعسار التي تعتمد على تحقيق نتيجة؟","o":["%10 من صافي المبالغ المحصلة","%5 من صافي المبالغ المحصلة","%50 من صافي المبالغ المحصلة","%20 من صافي المبالغ المحصلة"],"a":0},{"q":"متى تسدد الأتعاب المتغيرة لوكيل الإعسار؟","o":["عند انتهاء إجراءات الإعسار","عند صدور قرار إشهار الإعسار","على دفعات شهرية","عند اعتماد خطة التصفية"],"a":0},{"q":"تحدد الأتعاب المتغيرة لوكيل الإعسار بناء على:","o":["المبالغ المستردة بإجراءات عدم نفاذ التصرفات أو المحصلة بأحكام المسؤولية الشخصية لمديري المدين","صافي قيمة ذمة الإعسار وفق جدول الأتعاب","عدد الدائنين وعدد العاملين لدى المدين","مدة إجراءات الإعسار"],"a":0}]},{"n":"38","chapter":"الفصل الخامس - معايير تقدير أتعاب وكلاء الإعسار","notes":[],"source":"لا تخضع الأتعاب المقررة لوكيل الإعسار بصفته المشرف على تنفيذ خطة إعادة التنظيم للأحكام الواردة في هذا الفصل ويحق للمحكمة أن تحددها عند تكليفه بالاشراف على تنفيذ الخطة بناء على المدة المتوقعة للتنفيذ .","title":"أتعاب الإشراف على خطة إعادة التنظيم","memo":"⭐ لا تخضع أتعاب وكيل الإعسار بصفته مشرفا على تنفيذ خطة إعادة التنظيم لأحكام فصل الأتعاب\n⭐ تحددها المحكمة عند تكليفه بالإشراف بناء على المدة المتوقعة للتنفيذ","qs":[{"q":"على أي أساس تحدد المحكمة أتعاب وكيل الإعسار بصفته المشرف على تنفيذ خطة إعادة التنظيم؟","o":["المدة المتوقعة للتنفيذ","جدول الأتعاب الملحق بالنظام","صافي المبالغ المحصلة","عدد الدائنين"],"a":0},{"q":"هل تخضع أتعاب وكيل الإعسار بصفته المشرف على تنفيذ خطة إعادة التنظيم لأحكام فصل معايير تقدير الأتعاب؟","o":["لا تخضع لها","تخضع لها بالكامل","تخضع لأحكام الأتعاب المتغيرة فقط","تخضع للحد الأعلى في جدول الأتعاب فقط"],"a":0}]},{"n":"39","chapter":"الفصل الخامس - معايير تقدير أتعاب وكلاء الإعسار","notes":[],"source":"أ. لوكيل الاعسار ولأي من دائني الإعسار الاعتراض على قرار المحكمة بتحديد أتعاب وكيل الإعسار خلال خمسة أيام من تاريخ صدورها.\nب. للمحكمة دعوة المعترض لسماع أقواله حول أسباب الاعتراض على ان يتم البت في الاعتراضات المقدمة خلال خمسة أيام من تاريخ تقديمها ويكون قرار المحكمة قابلا للاستئناف.","title":"الاعتراض على قرار الأتعاب","memo":"⭐ لوكيل الإعسار ولأي دائن الاعتراض على قرار تحديد الأتعاب خلال (5) أيام من صدوره\n⭐ تبت المحكمة في الاعتراض خلال (5) أيام من تقديمه وقرارها قابل للاستئناف","qs":[{"q":"ما مدة الاعتراض على قرار المحكمة بتحديد أتعاب وكيل الإعسار؟","o":["خمسة أيام من تاريخ صدوره","عشرة أيام من تاريخ صدوره","ثلاثون يوما من تاريخ تبلغه","سبعة أيام من تاريخ صدوره"],"a":0},{"q":"ما طبيعة قرار المحكمة في الاعتراض على أتعاب وكيل الإعسار؟","o":["قابل للاستئناف","قطعي غير قابل للطعن","قابل للتمييز فقط","قابل للاعتراض أمام لجنة وكلاء الإعسار"],"a":0},{"q":"من يحق له الاعتراض على قرار المحكمة بتحديد أتعاب وكيل الإعسار؟","o":["وكيل الإعسار وأي من دائني الإعسار","لجنة وكلاء الإعسار فقط","المدين فقط","المسجل"],"a":0}]},{"n":"40","chapter":"الفصل الخامس - معايير تقدير أتعاب وكلاء الإعسار","notes":[],"source":"أ. مع مراعاة أحكام القانون وهذا النظام، يلتزم وكيل الإعسار بتضمين خطة التصفية إجراءات بيع أموال ذمه الاعسار بشكل يحقق أكبر عاند ممكن لصالح الدائنين بحيث يبذل الجهد لبيع وحدات النشاط الاقتصادي كلها او بعضها بصفتها عاملة ومنتجه وفي حال تعذر ذلك يتم بيعها بشكل متفرق تحت طائلة رفض الخطة .\nب. يتم البيع بأي من الوسائل التالية:\n1. المزاد العلني.\n2. المناقصة.\n3. التفاوض المباشر مع المشتري، على ان لا يتم اللجوء إلى هذه الوسيلة إلا إذا تعذر البيع بالوسيلتين المنصوص عليهما في البندين (1) و (2) من هذه الفقرة أو اذا كان البيع بأي منهما يحقق عائدا أقل.\nج. لوكيل الاعسار أن يقدم طلبا للمحكمة لتعديل إجراءات البيع وشروطه التي تضمنتها خطة التصفية المعتمدة من المحكمة ، وفي هذه الحال تصدر المحكمة قرارا باعتماد الخطة المعدلة.","title":"إجراءات البيع في خطة التصفية","memo":"⭐ يبذل الوكيل الجهد لبيع وحدات النشاط عاملة ومنتجة وإلا تباع متفرقة، تحت طائلة رفض الخطة\n⭐ وسائل البيع: المزاد العلني، المناقصة، التفاوض المباشر\n⭐ لا يلجأ للتفاوض المباشر إلا إذا تعذر البيع بالمزاد أو المناقصة أو حققا عائدا أقل\n⭐ للوكيل طلب تعديل إجراءات البيع وتصدر المحكمة قرارا باعتماد الخطة المعدلة","qs":[{"q":"متى يجوز اللجوء إلى البيع بالتفاوض المباشر مع المشتري؟","o":["إذا تعذر البيع بالمزاد العلني والمناقصة أو كان البيع بأي منهما يحقق عائدا أقل","في جميع الأحوال بحسب اختيار وكيل الإعسار","إذا وافقت لجنة الدائنين فقط","إذا كان المال مثقلا بحق عيني"],"a":0},{"q":"الأصل في بيع أموال ذمة الإعسار وفق خطة التصفية أن يبذل وكيل الإعسار الجهد لبيع:","o":["وحدات النشاط الاقتصادي بصفتها عاملة ومنتجة","الأموال بشكل متفرق","العقارات قبل المنقولات","الأموال الأعلى قيمة أولا"],"a":0},{"q":"ما الجزاء إذا لم تتضمن خطة التصفية إجراءات بيع تحقق أكبر عائد ممكن للدائنين؟","o":["رفض الخطة","عزل وكيل الإعسار","فرض غرامة على وكيل الإعسار","وقف إجراءات الإعسار"],"a":0}]},{"n":"41","chapter":"الفصل السادس - بيع الأموال في حالة التصفية","notes":[],"source":"أ. يشترط في خطة التصفية ان تتضمن تفاصيل أموال ذمة الإعسار التي سيتم بيعها، وبيان الآلية المقترحة للبيع وتكلفته بما في ذلك الأتعاب المترتبة على تقييمها.\nب. على وكيل الإعسار أن يرفق بخطة التصفية المقترحة تقريرا صادرا عن خبير يتم تعيينه بموافقة المحكمة يتضمن مقارنة بين العوائد المتوقعة من بيع وحدات النشاط الاقتصادي كلها او بعضها بصفتها عاملة ومنتجة أو بيع حصص أو أسهم المدين، اذا كان شخصا اعتباريا من جهة ، وبيع أموال المدين بشكل متفرق من جهة اخرى .","title":"محتويات خطة التصفية وتقرير الخبير","memo":"⭐ تتضمن الخطة تفاصيل الأموال المراد بيعها وآلية البيع وتكلفته بما فيها أتعاب التقييم\n⭐ يرفق بها تقرير خبير يعين بموافقة المحكمة يقارن بين البيع كوحدات عاملة أو بيع الحصص والأسهم وبين البيع المتفرق","qs":[{"q":"يعين الخبير الذي يعد التقرير المرفق بخطة التصفية:","o":["بموافقة المحكمة","بقرار لجنة الدائنين","بقرار لجنة وكلاء الإعسار","بقرار المدين"],"a":0},{"q":"ماذا يتضمن تقرير الخبير المرفق بخطة التصفية المقترحة؟","o":["مقارنة بين عوائد البيع كوحدات عاملة ومنتجة أو بيع الحصص والأسهم وبين بيع الأموال بشكل متفرق","قائمة الدائنين ومطالباتهم","تقييم أداء وكيل الإعسار","خطة إعادة تنظيم بديلة"],"a":0}]},{"n":"42","chapter":"الفصل السادس - بيع الأموال في حالة التصفية","notes":[],"source":"أ. إذا كانت الأموال المراد بيعها ذات طبيعة خاصة وتباع في سوق معين أو باتباع طريقة معينة فيجوز لوكيل الإعسار بموافقة المحكمة تعيين وسيط متخصص لإجراء البيع.\nب. تباع الأوراق المالية والمعادن الثمينة وأي أموال يحدد سعر بيعها من خلال السوق المالي او سوق معينة أخرى بسعرها في ذلك السوى.\nج. إذا كان البيع عن طريق المزاد العلني أو المناقصة فعلى وكيل الإعسار نشر إعلان البيع في صحيفتين يوميتين واسعتي الانتشار وعلى الموقع الإلكتروني للمدين قبل عشرة أيام على الأقل من موعد البيع على أن يتضمن الإعلان وصفا للمال المزمع بيعه وشروط البيع بما في ذلك الثمن والوقت المحددان لمعاينته .\nد. يشترط لإتمام بيع المال المثقل بحق عيني سواء بشكل متفرق أو جزءا من وحدة نشاط اقتصادي بالتفاوض المباشر مع المشتري إشعار صاحب الحق العيني بذلك.","title":"أحكام خاصة بالبيع والإعلان","memo":"⭐ للوكيل بموافقة المحكمة تعيين وسيط متخصص لبيع الأموال ذات الطبيعة الخاصة\n⭐ الأوراق المالية والمعادن الثمينة تباع بسعرها في السوق\n⭐ إعلان المزاد أو المناقصة في صحيفتين يوميتين وعلى الموقع الإلكتروني للمدين قبل (10) أيام على الأقل\n⭐ بيع المال المثقل بحق عيني بالتفاوض المباشر يشترط إشعار صاحب الحق العيني","qs":[{"q":"متى يجب نشر إعلان البيع بالمزاد العلني أو المناقصة؟","o":["قبل عشرة أيام على الأقل من موعد البيع","قبل خمسة أيام على الأقل","قبل ثلاثين يوما على الأقل","قبل سبعة أيام على الأقل"],"a":0},{"q":"أين ينشر وكيل الإعسار إعلان البيع بالمزاد العلني أو المناقصة؟","o":["في صحيفتين يوميتين واسعتي الانتشار وعلى الموقع الإلكتروني للمدين","في الجريدة الرسمية فقط","في سجل الإعسار فقط","في صحيفة يومية واحدة"],"a":0},{"q":"تباع الأوراق المالية والمعادن الثمينة المملوكة لذمة الإعسار:","o":["بسعرها في السوق المالي أو السوق المعينة التي يحدد فيها سعرها","بالمزاد العلني حصرا","بالسعر الذي تحدده لجنة الدائنين","بالتفاوض المباشر بسعر يقدره الخبير"],"a":0},{"q":"يجوز لوكيل الإعسار تعيين وسيط متخصص لبيع الأموال ذات الطبيعة الخاصة:","o":["بموافقة المحكمة","بموافقة لجنة الدائنين","دون حاجة لموافقة أي جهة","بموافقة المدين"],"a":0}]},{"n":"43","chapter":"الفصل السادس - بيع الأموال في حالة التصفية","notes":[],"source":"أ. على وكيل الاعسار اشعار قاضي المحكمة ولجنة الدائنين، ان وجدت قبل عشرة أيام من التاريخ المحدد للبيع بالمزاد العلني او بالمناقصة او بالتفاوض المباشر مع المشتري بنيته بيع أي من الأموال وذلك بغض النظر عن خطة البيع وطريقة البيع وتاريخ اتمامه .\nب. يجب ان يتضمن الإشعار ما يلي:\n1. مكان وجود المال المراد بيعه.\n2. وصفا مفصلا للمال مع بيان استخداماته.\n3. الحد الأدنى لسعر البيع (مبلغ افتتاح المزاودة) في حال البيع في المزاد العلني.\n4. القيمة المقدرة للمال وإجراءات الإحالة في حال البيع بالمناقصة.\n5. القيمة المقدرة للمال ومعلومات المشتري المزمع التفاوض معه وشروط البيع بما في ذلك السعر وشروط تسديد الثمن في حال البيع بالتفاوض المباشر مع المشتري.\nج.1. إذا كان المال المزمع بيعه مثقلا بحق عيني، وكانت حصيلة البيع لا تكفي لسداد الدين المضمون بهذا الحق، فيحق للدائنين أصحاب الحقوق المضمونة به الاعتراض على البيع للمحكمة خلال مدة خمسة أيام من استلام الإشعار المنصوص عليه في الفقرة (أ) من هذه المادة على أن تبين أسباب الاعتراض وله التمسك بإمكانية البيع بشروط أفضل من الشروط المعروضة.\n2. للمحكمة أن تستمع لأقوال المعترض ووكيل الإعسار وتتخذ قرارا نهائيا بخصوص الاعتراض خلال مدة سبعة أيام من تاريخ تقديمه ويستأخر البيع إلى حين صدور القرار.\nد.1. تؤول حصيلة بيع الأموال خالية من أي حقوق عينية لذمة الاعسار ويتم توزيعها وفق أحكام القانون.\n2. إذا كان المال الذي تم بيعه مثقلا بحقوق عينية لصالح أكثر من جهة فتستخدم حصيلة البيع لسداد مصاريف البيع والمصاريف الأخرى اللازمة لإتمام البيع بما في ذلك رسوم تقييم المال والإعلان والمصاريف القضائية وأتعاب وكيل الإعسار، حسب مقتضى الحال، ويستخدم الرصيد لسداد الديون المضمونة بالمال المباع وفقا للأولويات المنصوص عليها في القانون ويؤول الفائض لذمة الإعسار ويوزع على الدائنين وفق أحكام القانون.\nهـ،. على وكيل الاعسار اشعار قاضي المحكمة ولجنة الدائنين، ان وجدت والدائنين أصحاب الحقوق العينية على المال المباع خلال مدة لا تزيد على سبعة أيام من تاريخ إتمام البيع مع بيان تفاصيل البيع بما في ذلك الثمن.\nو. على قاضي المحكمة بعد إتمام إجراءات البيع سواء بالمزاد العلني او بالمناقصة او بالبيع المباشر اصدار قرار بإعلان إتمام البيع ومخاطبة الجهة المختصة بتسجيل المال المباع، ان وجدت، لغايات تسجيل المال باسم المشتري خاليا من أي حقوق، وتسجل أي مبالغ مستحقة على ذمة الاعسار بسبب ملكية المال بما في ذلك الضرائب والرسوم دينا عليها.","title":"إشعار البيع والاعتراض وتوزيع الحصيلة","memo":"⭐ يشعر الوكيل القاضي ولجنة الدائنين قبل (10) أيام من موعد البيع\n⭐ للدائن المضمون الاعتراض خلال (5) أيام من استلام الإشعار إذا كانت الحصيلة لا تكفي، وتبت المحكمة نهائيا خلال (7) أيام ويستأخر البيع\n⭐ حصيلة المال المثقل: تسدد مصاريف البيع أولا ثم الديون المضمونة والفائض لذمة الإعسار\n⭐ يشعر الوكيل بتفاصيل البيع خلال مدة لا تزيد على (7) أيام من إتمامه","qs":[{"q":"يشعر وكيل الإعسار قاضي المحكمة ولجنة الدائنين بنيته بيع أي من الأموال قبل التاريخ المحدد للبيع بـ:","o":["عشرة أيام","خمسة أيام","سبعة أيام","ثلاثة أيام"],"a":0},{"q":"ما المدة المتاحة للدائن صاحب الحق المضمون للاعتراض على بيع المال المثقل بحقه إذا كانت الحصيلة لا تكفي لسداد دينه؟","o":["خمسة أيام من استلام الإشعار","عشرة أيام من استلام الإشعار","سبعة أيام من تاريخ البيع","ثلاثة أيام من استلام الإشعار"],"a":0},{"q":"خلال أي مدة تتخذ المحكمة قرارها النهائي في اعتراض الدائن المضمون على البيع؟","o":["سبعة أيام من تاريخ تقديمه","خمسة أيام من تاريخ تقديمه","عشرة أيام من تاريخ تقديمه","يوم واحد من تاريخ تقديمه"],"a":0},{"q":"بيع مال مثقل بحقوق عينية لأكثر من جهة، فبماذا تبدأ المحكمة عند استخدام حصيلة البيع؟","o":["سداد مصاريف البيع والمصاريف اللازمة لإتمامه","سداد الديون المضمونة بالمال المباع","توزيع الحصيلة على الدائنين غير المضمونين","سداد الديون الممتازة"],"a":0}]},{"n":"44","chapter":"الفصل السادس - بيع الأموال في حالة التصفية","notes":[],"source":"أ. مع مراعاة أحكام البند (1) من الفقرة (ج) من المادة (100) من القانون على وكيل الإعسار البدء بإجراءات بيع الأموال المثقلة بالحقوق العينية في موعد لا يتجاوز شهرين من تاريخ اعتماد خطة التصفية من المحكمة وفقا لأحكام الفقرة (ج) من المادة (101) من القانون وللمحكمة تمديد المدة بناء على طلب وكيل الإعسار لمدة مماثلة ولمرة واحدة فقط.\nب. لا يتم بيع الأموال التي هي موضوع طلب فصل عن ذمة الاعسار وفقا للإجراءات المحددة في المادة (2 4) من القانون ما لم يتم البت في الطلب، ويبدأ احتساب المدة المنصوص عليها في الفقرة (أ) من هذه المادة من تاريخ صيرورة قرار المحكمة بخصوص رفض طلب الفصل نهائيا.","title":"موعد بيع الأموال المثقلة بالحقوق العينية","memo":"⭐ يبدأ الوكيل بإجراءات بيع الأموال المثقلة بحقوق عينية خلال مدة لا تتجاوز شهرين من اعتماد خطة التصفية\n⭐ للمحكمة التمديد بطلب الوكيل لمدة مماثلة ولمرة واحدة فقط\n⭐ لا تباع الأموال موضوع طلب الفصل قبل البت فيه، وتحتسب المدة من صيرورة قرار رفض الفصل نهائيا","qs":[{"q":"خلال أي مدة يبدأ وكيل الإعسار إجراءات بيع الأموال المثقلة بالحقوق العينية؟","o":["مدة لا تتجاوز شهرين من تاريخ اعتماد خطة التصفية من المحكمة","مدة لا تتجاوز شهرا من تاريخ اعتماد خطة التصفية","مدة لا تتجاوز ثلاثة أشهر من تاريخ إشهار الإعسار","مدة لا تتجاوز ستة أشهر من تاريخ اعتماد خطة التصفية"],"a":0},{"q":"هل يجوز تمديد مدة البدء بإجراءات بيع الأموال المثقلة بالحقوق العينية؟","o":["نعم، للمحكمة تمديدها بطلب وكيل الإعسار لمدة مماثلة ولمرة واحدة فقط","نعم، لمرات غير محددة بقرار المحكمة","نعم، بقرار لجنة الدائنين لمدة شهر","لا يجوز تمديدها مطلقا"],"a":0},{"q":"كانت أموال موضوع طلب فصل عن ذمة الإعسار ورفضت المحكمة الطلب، فمتى تبدأ مدة البدء بإجراءات بيعها؟","o":["من تاريخ صيرورة قرار رفض طلب الفصل نهائيا","من تاريخ تقديم طلب الفصل","من تاريخ اعتماد خطة التصفية","من تاريخ إشهار الإعسار"],"a":0}]},{"n":"45","chapter":"الفصل السادس - بيع الأموال في حالة التصفية","notes":[],"source":"أ. إذا كان المدين شريكا في مال شائع فللمحكمة قسمة المال دون اتباع الإجراءات المنصوص عليها في القوانين ذات العلاقة ولا يعتد بأي قيد قانوني او شرط عقدي يقضي بعدم جواز قسمة المال الشائع وذلك دون الإخلال بحق شركاء المدين في المطالبة بأي حقوق مستحقة لهم في ذمة المدين نتيجة الملكية الشائعة.\nب. لغايات هذه المادة يعتبر أي مما يلي مالا شائعا:\n1. الحصص في شركات الأشخاص والحقوق الممنوحة بموجب اتفاقيات الائتلاف والاتفاقيات المشابهة.\n2. الحصة الشائعة في مال منقول أو غير منقول.","title":"قسمة المال الشائع","memo":"⭐ إذا كان المدين شريكا في مال شائع فللمحكمة قسمته دون اتباع إجراءات القوانين ذات العلاقة\n⭐ لا يعتد بأي قيد قانوني أو شرط عقدي يمنع القسمة، دون إخلال بحقوق شركاء المدين\n⭐ المال الشائع يشمل الحصص في شركات الأشخاص وحقوق اتفاقيات الائتلاف والحصة الشائعة في مال منقول أو غير منقول","qs":[{"q":"كان المدين شريكا في مال شائع وتضمن عقد الشراكة شرطا بعدم جواز القسمة، فما حكم هذا الشرط في إجراءات الإعسار؟","o":["لا يعتد به، وللمحكمة قسمة المال","يعتد به ويمنع القسمة","يعتد به ما لم يوافق الشركاء على القسمة","يوقف إجراءات الإعسار حتى انتهاء مدة الشرط"],"a":0},{"q":"أي مما يلي لا يعتبر مالا شائعا لغايات أحكام قسمة المال الشائع في نظام الإعسار؟","o":["الأسهم في شركة مساهمة عامة","الحصص في شركات الأشخاص","الحقوق الممنوحة بموجب اتفاقيات الائتلاف","الحصة الشائعة في مال غير منقول"],"a":0}]},{"n":"46","chapter":"الفصل السادس - بيع الأموال في حالة التصفية","notes":[],"source":"أ. يجوز أن تتضمن خطة التصفية بيع المدين إذا كان شخصا اعتباريا عن طريق بيع الحصص أو الأسهم فيه على أن يرفق وكيل الإعسار او المصفي في الخطة تقريرا من خبير أو أكثر توافق عليه المحكمة يتضمن مقارنة بين العوائد المتأتية من بيع الحصص أو الأسهم من جهة وبيع أموال وموجودات المدين بشكل متفرق من جهه أخرى.\nب. للمحكمة أن تقرر استثناء الأموال المثقلة بالحق العيني من أصول المدين عند تقييم الحصص أو الأسهم وعلى وكيل الإعسار إعادة تقييم الحصص أو الأسهم لغايات تخفيض قيمة الأموال التي تم استثناؤها.\nج. يجب أن يتضمن عقد بيع حصص المدين أو أسهمه نصا صريحا باستثناء الأموال المنصوص عليها في الفقرة (ب) من هذه المادة من البيع.","title":"بيع المدين الاعتباري ببيع حصصه أو أسهمه","memo":"⭐ يجوز أن تتضمن خطة التصفية بيع المدين الاعتباري ببيع حصصه أو أسهمه مع تقرير خبير أو أكثر توافق عليه المحكمة\n⭐ للمحكمة استثناء الأموال المثقلة بالحق العيني عند تقييم الحصص أو الأسهم ويعاد التقييم\n⭐ يجب أن يتضمن عقد البيع نصا صريحا باستثناء تلك الأموال","qs":[{"q":"عند بيع المدين الاعتباري عن طريق بيع حصصه أو أسهمه، يرفق وكيل الإعسار بالخطة تقريرا من:","o":["خبير أو أكثر توافق عليه المحكمة","مدقق حسابات المدين","لجنة الدائنين","هيئة الأوراق المالية"],"a":0},{"q":"إذا قررت المحكمة استثناء الأموال المثقلة بالحق العيني من أصول المدين عند تقييم الحصص أو الأسهم، فإنه يجب:","o":["أن يتضمن عقد البيع نصا صريحا باستثناء هذه الأموال من البيع","أن تباع هذه الأموال مع الحصص بسعر أعلى","أن توافق لجنة وكلاء الإعسار على الاستثناء","أن تنقل هذه الأموال لحساب نفقات حالات الإعسار بلا أموال"],"a":0}]},{"n":"47","chapter":"الفصل السادس - بيع الأموال في حالة التصفية","notes":[],"source":"أ. تقرر المحكمة بعد استكمال إجراءات بيع حصص أو أسهم المدين تعليق إجراءات الإعسار.\nب. بعد إتمام إجراءات نقل ملكية حصص المدين أو أسهمه وتسجيلها باسم المشتري، تنتهي إجراءات الإعسار بمواجهة الشركة التي تم بيع حصصها أو أسهمها بشكل نهائي وتستأنف في مواجهة ذمة الإعسار التي تتكون حصرا من:\n1. حصيلة بيع حصص المدين أو أسهمه.\n2. الأموال المستثناة من أصول المدين وفقا لأحكام الفقرتين (ب) و(ج) من المادة (46) من هذا النظام .","title":"آثار بيع حصص المدين أو أسهمه","memo":"⭐ بعد استكمال بيع الحصص أو الأسهم تقرر المحكمة تعليق إجراءات الإعسار\n⭐ بعد نقل الملكية تنتهي الإجراءات نهائيا بمواجهة الشركة وتستأنف بمواجهة ذمة الإعسار المكونة حصرا من: حصيلة البيع والأموال المستثناة","qs":[{"q":"ما الذي تقرره المحكمة بعد استكمال إجراءات بيع حصص أو أسهم المدين؟","o":["تعليق إجراءات الإعسار","إنهاء إجراءات الإعسار نهائيا","بدء مرحلة إعادة التنظيم","شطب الشركة من سجل الشركات"],"a":0},{"q":"بعد نقل ملكية حصص أو أسهم المدين للمشتري، تتكون ذمة الإعسار التي تستأنف الإجراءات بمواجهتها حصرا من:","o":["حصيلة بيع الحصص أو الأسهم والأموال المستثناة من أصول المدين","جميع أموال الشركة المبيعة","حصيلة البيع فقط","الأموال المستثناة فقط"],"a":0}]},{"n":"48","chapter":"الفصل السادس - بيع الأموال في حالة التصفية","notes":[],"source":"في حال بيع حصص المدين أو أسهمه ، إذا كان شخصا اعتباريا، أو بيع أمواله كافة، أو أي جزء منها، يكون للدائنين أصحاب الحقوق المضمونة بتلك الأموال أولوية في استيفاء حقوقهم من حصيلة البيع وفقا لأحكام القانون، وتحدد الأولوية بالاستيفاء بنسبة الأموال التي تضمن حقوقهم إلى كامل القيمة المقدرة للأموال العائدة للمدين التي تم بيعها.","title":"أولوية الدائنين المضمونين عند البيع","memo":"⭐ للدائنين أصحاب الحقوق المضمونة أولوية في الاستيفاء من حصيلة البيع وفق القانون\n⭐ تحدد الأولوية بنسبة الأموال الضامنة لحقوقهم إلى كامل القيمة المقدرة لأموال المدين المبيعة","qs":[{"q":"عند بيع حصص المدين أو أسهمه أو أمواله، كيف تحدد أولوية الدائنين المضمونين في الاستيفاء؟","o":["بنسبة الأموال التي تضمن حقوقهم إلى كامل القيمة المقدرة لأموال المدين المبيعة","بنسبة ديونهم إلى إجمالي ديون الإعسار","بحسب أسبقية تسجيل حقوقهم","بالتساوي بين جميع الدائنين"],"a":0},{"q":"من له الأولوية في استيفاء حقوقه من حصيلة بيع الأموال الضامنة؟","o":["الدائنون أصحاب الحقوق المضمونة بتلك الأموال","الدائنون أصحاب الديون غير المضمونة","وكيل الإعسار","العاملون لدى المدين"],"a":0}]},{"n":"49","chapter":"الفصل السادس - بيع الأموال في حالة التصفية","notes":[],"source":"أ. إذا كان المال المراد بيعه بالتفاوض المباشر مع المشتري مثقلا بحق عيني، فيحق لصاحب الحق العيني أن يتقدم بطلب لشرائه إلى المحكمة أو إلى وكيل الإعسار بالسعر المعروض أو بسعر أفضل إما مباشرة أو من خلال حليف له، إذا كان شخصا اعتباريا.\nب. إذا كان عرض الشراء المقدم وفقا لأحكام الفقرة (أ) من هذه المادة مكتملا فيتم بيع المال موضوع الطلب لصاحب الحق العيني أو حليفه، حسب مقتضى الحال وله إجراء التقاص بين الحق المضمون بالمال الذي اشتراه وحصيلة البيع.","title":"حق صاحب الحق العيني في الشراء","memo":"⭐ عند البيع بالتفاوض المباشر لمال مثقل بحق عيني، لصاحب الحق تقديم طلب شرائه للمحكمة أو للوكيل بالسعر المعروض أو أفضل مباشرة أو عبر حليفه\n⭐ إذا اكتمل العرض يباع له وله إجراء التقاص بين حقه المضمون وحصيلة البيع","qs":[{"q":"عند بيع مال مثقل بحق عيني بالتفاوض المباشر، يجوز لصاحب الحق العيني أن يتقدم بطلب شرائه:","o":["بالسعر المعروض أو بسعر أفضل","بسعر أقل بمقدار دينه","بالقيمة الدفترية للمال","بسعر تحدده لجنة الدائنين"],"a":0},{"q":"اشترى صاحب الحق العيني المال المثقل بحقه وفق النظام، فما الذي يحق له؟","o":["إجراء التقاص بين الحق المضمون بالمال وحصيلة البيع","استرداد كامل الثمن من ذمة الإعسار","الإعفاء من رسوم التسجيل","التقدم على مصاريف البيع"],"a":0}]},{"n":"50","chapter":"الفصل السادس - بيع الأموال في حالة التصفية","notes":[],"source":"إذا كان سعر الشراء المعروض عند بيع وحدات النشاط الاقتصادي بصفتها عاملة ومنتجة سواء كليا أو جزئيا أو بيع حصص أو أسهم المدين، إذا كان شخصا اعتباريا، يقل عن ما نسبته (50) من القيمة المقدرة التي اعتمدتها المحكمة، فلا يجوز السير بإجراءات البيع إلا بعد الحصول على موافقة لجنة الدائنين، إن وجدت.","title":"البيع بأقل من نصف القيمة المقدرة","memo":"⭐ إذا قل سعر الشراء المعروض لوحدات النشاط العاملة أو لحصص وأسهم المدين عن (50%) من القيمة المقدرة المعتمدة من المحكمة فلا يجوز السير بالبيع إلا بموافقة لجنة الدائنين إن وجدت","qs":[{"q":"عرض مشتر لشراء وحدة نشاط اقتصادي عاملة سعرا يعادل %40 من القيمة المقدرة التي اعتمدتها المحكمة، فما الحكم؟","o":["لا يجوز السير بالبيع إلا بعد موافقة لجنة الدائنين إن وجدت","يجوز البيع بقرار وكيل الإعسار وحده","يرفض العرض حكما","يجب الحصول على موافقة لجنة وكلاء الإعسار"],"a":0},{"q":"ما النسبة من القيمة المقدرة التي إذا قل عنها سعر الشراء المعروض اشترطت موافقة لجنة الدائنين؟","o":["%50","%75","%25","%10"],"a":0}]},{"n":"51","chapter":"الفصل السادس - بيع الأموال في حالة التصفية","notes":[],"source":"أ. مع مراعاة أحكام الفقرة (ج) من المادة (9 5) من القانون، على وكيل الإعسار تقديم طلب خطي إلى المحكمة قبل بيع الأموال المعرضة للتلف أو لنقصان القيمة دون مراعاة الإجراءات المنصوص عليها في هذا الفصل.\nب. على المحكمة إصدار قرار بخصوص الطلب المقدم وفقا لأحكام الفقرة (أ) من هذه المادة خلال مدة لا تتجاوز يوما واحدا من تاريخ تقديمه وفي حال عدم إصدار القرار فلوكيل الإعسار السير في إجراءات البيع .","title":"بيع الأموال المعرضة للتلف","memo":"⭐ يقدم الوكيل طلبا خطيا للمحكمة قبل بيع الأموال المعرضة للتلف أو نقصان القيمة دون مراعاة إجراءات الفصل\n⭐ تصدر المحكمة قرارها خلال مدة لا تتجاوز يوما واحدا، وإلا فللوكيل السير في البيع","qs":[{"q":"خلال أي مدة تصدر المحكمة قرارها في طلب بيع الأموال المعرضة للتلف أو لنقصان القيمة؟","o":["مدة لا تتجاوز يوما واحدا من تاريخ تقديمه","ثلاثة أيام","خمسة أيام","سبعة أيام"],"a":0},{"q":"قدم وكيل الإعسار طلبا لبيع بضائع معرضة للتلف ولم تصدر المحكمة قرارها خلال المدة المحددة، فما الحكم؟","o":["لوكيل الإعسار السير في إجراءات البيع","يعتبر الطلب مرفوضا","يجب عرض الأمر على لجنة الدائنين","يجب إعادة تقديم الطلب"],"a":0}]},{"n":"52","chapter":"الفصل السادس - بيع الأموال في حالة التصفية","notes":[],"source":"للمحكمة بناء على طلب وكيل الاعسار، وبعد الاستماع لأقوال المدين ولجنة الدائنين، إن وجدت:\nأ. أن تسمح لوكيل الإعسار بالتنازل عن أي أموال أو حقوق عائدة لذمة الإعسار لصالح الخزينة أو أي مؤسسة عامة أو جمعية خيرية عند تعذر بيعها أو إذا كان في بيعها ضررا لذمة الإعسار.\nب. ان تقرر شطب الديون والذمم المتعذر تحصيلها او التي تزيد كلفة تحصيلها على قيمتها.","title":"التنازل عن الأموال وشطب الديون","memo":"⭐ للمحكمة بطلب الوكيل وبعد سماع المدين ولجنة الدائنين السماح بالتنازل عن أموال لصالح الخزينة أو مؤسسة عامة أو جمعية خيرية عند تعذر بيعها أو إضرار بيعها بالذمة\n⭐ للمحكمة شطب الديون المتعذر تحصيلها أو التي تزيد كلفة تحصيلها على قيمتها","qs":[{"q":"لصالح أي جهة يجوز للمحكمة أن تسمح لوكيل الإعسار بالتنازل عن أموال ذمة الإعسار عند تعذر بيعها؟","o":["الخزينة أو أي مؤسسة عامة أو جمعية خيرية","أي من الدائنين المضمونين","المدين نفسه","وكيل الإعسار مقابل أتعابه"],"a":0},{"q":"يجوز للمحكمة أن تقرر شطب الديون والذمم المستحقة لذمة الإعسار إذا كانت:","o":["متعذرة التحصيل أو تزيد كلفة تحصيلها على قيمتها","تقل قيمتها عن خمسمائة دينار","مستحقة على العاملين لدى المدين","مضى على استحقاقها سنة"],"a":0},{"q":"قبل أن تسمح المحكمة بالتنازل عن أموال ذمة الإعسار، عليها:","o":["الاستماع لأقوال المدين ولجنة الدائنين إن وجدت","الحصول على موافقة لجنة وكلاء الإعسار","الحصول على موافقة الوزير","نشر إعلان في صحيفتين يوميتين"],"a":0}]},{"n":"53","chapter":"الفصل السادس - بيع الأموال في حالة التصفية","notes":[],"source":"يلغى نظام تصفية الشركات رقم (122) لسنة 02017","title":"إلغاء نظام تصفية الشركات","memo":"⭐ يلغى نظام تصفية الشركات رقم (122) لسنة 2017","qs":[{"q":"ما النظام الذي ألغاه نظام الإعسار لسنة 2019؟","o":["نظام تصفية الشركات","نظام رسوم تسجيل الشركات","نظام المؤسسات الفردية","نظام سجل الأموال المنقولة"],"a":0}]},{"n":"54","chapter":"الفصل السادس - بيع الأموال في حالة التصفية","notes":[],"source":"يصدر الوزير التعليمات اللازمة لتنفيذ أحكام هذا النظام.\nملحق جدول اتعاب وكلاء الاعسار صافي ذمة الاعسار النسبة المئوية الحد الادنى الحد الاعلى من 1 الى 000ر100 %7 %10 من001ر100 الى 000ر300 %5 %8 من 001ر300 الى 000ر000ر1 5ر%3 %6 من 001ر000ر1 الى 000ر000ر10 %2 %4 ما فوق ال 000ر000ر10 %1 %2","title":"تعليمات التنفيذ وجدول الأتعاب","memo":"⭐ يصدر الوزير التعليمات اللازمة لتنفيذ أحكام النظام\n⭐ جدول الأتعاب: حتى 100,000 (7%-10%)، 100,001-300,000 (5%-8%)، 300,001-1,000,000 (3.5%-6%)، 1,000,001-10,000,000 (2%-4%)، فوق 10,000,000 (1%-2%)","qs":[{"q":"من يصدر التعليمات اللازمة لتنفيذ أحكام نظام الإعسار؟","o":["الوزير","لجنة وكلاء الإعسار","المراقب","مجلس الوزراء"],"a":0},{"q":"وفق جدول أتعاب وكلاء الإعسار، ما الحدان الأدنى والأعلى لنسبة الأتعاب إذا كان صافي ذمة الإعسار من 1 إلى 100,000 دينار؟","o":["%7 و %10","%5 و %8","%2 و %4","%1 و %2"],"a":0},{"q":"بلغ صافي ذمة الإعسار (5,000,000) دينار، فما الحد الأدنى لنسبة الأتعاب الثابتة وفق الجدول؟","o":["%2","%3.5","%1","%5"],"a":0}]}]};
